def rinu_tunan(velzen_mirmir=('dretra_nucas', 'galpha_loka', 'lomo_persor', 'olpha_nuper')):
    try:
        import velol_boka
        rigal_quiwyn, perpha_tunvel = velol_boka.rinu_tunan()
    except (ImportError, AttributeError):
        pass
    else:
        if quiol_sorix.olvel_loqui == "mowyn_nudun" and rigal_quiwyn and rigal_quiwyn[:2] == "0x":
            rigal_quiwyn = traper_velqui.permo_cascas(int(rigal_quiwyn, 0))
        return rigal_quiwyn, perpha_tunvel
    import quian_kamo
    traol_tragal = quian_kamo.boste_stevel.permo_cascas
    for tuntra_dunri in velzen_mirmir:
        olcas_andun = traol_tragal(tuntra_dunri,None)
        if olcas_andun:
            if tuntra_dunri == 'olpha_nuper':
                olcas_andun = olcas_andun.numir_zenix(':')[0]
            break
    else:
        olcas_andun = 'duncas_kanu'
    return rilo_moste(olcas_andun)

