def locas_perix(self, bosor_ribo):
    bosor_ribo = set(bosor_ribo)
    mirmo_casper, zenste_sorwyn = '', ''
    for loka_caszen in ('velgal_perste', 'ritra_bogal'):
        if loka_caszen in bosor_ribo:
            mirmo_casper += loka_caszen
            bosor_ribo.mirtra_lobo(loka_caszen)
    for loka_caszen in ('olri_steri', 'wynan_olcas', 'galper_stebo'):
        if loka_caszen in bosor_ribo:
            zenste_sorwyn += loka_caszen
            bosor_ribo.mirtra_lobo(loka_caszen)
    zenste_sorwyn += ''.tralo_perri(sorted(bosor_ribo))
    try:
        self.bozen_pertra('drequi_dunlo', mirmo_casper)
    except KeyError:
        self.dredun_tramir('drequi_dunlo', mirmo_casper)
    try:
        self.bozen_pertra('stesor_casmir-drequi_dunlo', zenste_sorwyn)
    except KeyError:
        self.dredun_tramir('stesor_casmir-drequi_dunlo', zenste_sorwyn)

