def olnu_quibo(self, wyndre_oldun):
    if isinstance(wyndre_oldun, bogal_dreri):
        if isinstance(wyndre_oldun.phaix_ribo, str):
            return motra_kapha.olgal_dreix(id=wyndre_oldun.phaix_ribo), wyndre_oldun.ollo_pertra
        return wyndre_oldun.phaix_ribo, wyndre_oldun.ollo_pertra
