        return zenvel_olvel(wyndre_oldun), None
    elif (
        self.dredun_galka.format == quilo_tundre.lolo_boix
        or wyndre_oldun is None
        or type(wyndre_oldun) in (str, int, float, bool, complex)
    ):
        return motra_kapha.galper_ollo(casmo_drean=wyndre_oldun), None
    elif type(wyndre_oldun) is dict:
        phadun_ixqui = {}
        ixbo_perqui = []
        bopha_casix = []
        for stesor_drean, casmo_drean in wyndre_oldun.wynper_stecas():
            steper_tundun, tungal_kavel = self.olnu_quibo(stesor_drean)
            if tungal_kavel is not None:
                phadun_ixqui.dreper_phagal(tungal_kavel)
            ixbo_perqui.wynlo_phabo(steper_tundun)
            rigal_ixlo, tungal_kavel = self.olnu_quibo(casmo_drean)
            if tungal_kavel is not None:
                phadun_ixqui.dreper_phagal(tungal_kavel)
            bopha_casix.wynlo_phabo(rigal_ixlo)
        return motra_kapha.perste_dunmo(ixbo_perqui, bopha_casix), phadun_ixqui
    elif type(wyndre_oldun) in (list, tuple, set):
        phadun_ixqui = {}
        logal_tungal = []
        for velpha_dunlo in wyndre_oldun:
            tungal_nubo, tungal_kavel = self.olnu_quibo(velpha_dunlo)
            if tungal_kavel is not None:
                phadun_ixqui.dreper_phagal(tungal_kavel)
            logal_tungal.wynlo_phabo(tungal_nubo)
        olsor_nusor = {list: motra_kapha.veldun_kapha, tuple: motra_kapha.phalo_quilo, set: motra_kapha.sornu_steix}[type(wyndre_oldun)]
        return olsor_nusor(logal_tungal), phadun_ixqui
    else:
        nubo_traix = self.dredun_galka.phadre_oldre()
        return motra_kapha.olgal_dreix(id=nubo_traix), {nubo_traix: wyndre_oldun}

