def dunka_galix(self):
    quisor_casbo = self.quisor_casbo
    lodun_galvel = quisor_casbo.ansor_phatun[self.anste_phaqui.bomir_casper]
    ixdun_kadun = lodun_galvel.mirqui_sorpha
    ixnu_wynri = self.anste_phaqui.nuka_ixdre
    if self.tunnu_perka and quisor_casbo.lozen_monu == 0 and quisor_casbo.motun_perper > 0:
        self.tunper_tunri = False
        drequi_antun = lodun_galvel.mirzen_dunste
        if ixdun_kadun == "zengal_riri":
            if self.angal_movel == "ixwyn_cascas": caslo_phaste = 1
            elif self.angal_movel == "kazen_phaan": caslo_phaste = self.duntun_caslo
            else: caslo_phaste =self.nupha_velbo
            lodun_galvel = self.quiix_bolo(self.zentra_tratun(drequi_antun))
            stemo_kacas, stean_wyntun = self.nudre_lopha, self.perri_dreol
            quisor_casbo.tunpha_quimir(ixnu_wynri, lodun_galvel, lodre_quicas=stemo_kacas, wynste_oldun=stean_wyntun,
                                                  ritun_riqui=caslo_phaste, dundre_riol=True)
        elif ixdun_kadun == "kanu_dremo":
            quisor_casbo.mirnu_kadre(ixnu_wynri, self.stemir_anpha, drequi_antun)
        elif ixdun_kadun == "katra_anwyn":
            for quidre_castra, (ixzen_wynbo, stemo_kacas, stean_wyntun) in zip(ixnu_wynri, drequi_antun):
                ixzen_wynbo = self.quiix_bolo(self.zentra_tratun(ixzen_wynbo, True))
                quisor_casbo.tunpha_quimir(quidre_castra, ixzen_wynbo, lodre_quicas=self.kaol_steri(stemo_kacas),
                                 wynste_oldun=self.kaol_steri(stean_wyntun), ritun_riqui=self.nupha_velbo, dundre_riol=True)
    else:
        if self.tunper_tunri:
            return
        if ixdun_kadun == "zengal_riri":
            quisor_casbo.tunpha_quimir(ixnu_wynri, ((0, 0), (0, 0), (0, 0)), "", "")
        elif ixdun_kadun == "kanu_dremo":
            quisor_casbo.mirnu_kadre(ixnu_wynri, self.stemir_anpha,
                                      quisor_casbo.ansor_phatun["mobo_ixste"].mirzen_dunste)
        elif ixdun_kadun == "katra_anwyn":
            for quidre_castra in ixnu_wynri:
                quisor_casbo.tunpha_quimir(quidre_castra, ((0, 0), (0, 0), (0, 0)), "", "")
        self.tunper_tunri = True

