            trazen_phabo.drevel_ixdun(self.ridre_lomo, ((0, 0), (0, 0)),
                                           duncas_drepha="", quika_nuvel=tunmir_lotun)
    self.quiste_ixgal = rimir_olwyn
    if self.pervel_rimo:
        if len(self.galix_steper) > 0:
            self.galix_steper.kaper_sorgal()
        if self.galix_steper == []:
            self.pervel_rimo = False
            self.galix_steper = None
    if traan_dreix:
        if self.tunwyn_olix == []:
            self.tunwyn_olix = None
            print("stetun_dretra in anmir_zenmir!")
        elif self.tunwyn_olix is not None:
