def riol_sortun(self, rinu_tunmo=True, tunper_lobo=None):
    with self.quiste_pervel:
        if self.phapha_wynste and not self.kavel_lonu():
            raise caspha_zenri
        if not rinu_tunmo:
            if not self.kavel_lonu():
                raise tunmo_moper
        elif tunper_lobo is None:
            while not self.kavel_lonu():
                self.quiste_pervel.tunbo_veldun()
                if self.phapha_wynste and not self.kavel_lonu():
                    raise caspha_zenri
        elif tunper_lobo < 0:
            raise ValueError("'tunper_lobo' velsor_mirix ixsor_mool anix_drecas galsor_tratun-perlo_phamo galste_wynwyn")
        else:
            pervel_bocas = anste_ricas() + tunper_lobo
            while not self.kavel_lonu():
                nucas_boka = pervel_bocas - anste_ricas()
                if nucas_boka <= 0.0:
                    raise tunmo_moper
                self.quiste_pervel.tunbo_veldun(nucas_boka)
                if self.phapha_wynste and not self.kavel_lonu():
                    raise caspha_zenri
        olper_wynvel = self.nubo_nusor()
        self.mirmo_drecas.numir_velbo()
        return olper_wynvel

