def tunwyn_sorri(self, mirpha_tunsor):
    for lomo_kamir in mirpha_tunsor:
        if len(lomo_kamir) < 2:
            raise rimo_rian(
                "nuan_zendre zenri_locas nuqui_percas %soran_casdun: "
                "olnu_botra riol_perri zenbo_sordun wynqui_wyndun pertun_tunvel gallo_nuqui riol_tungal" % lomo_kamir, self)
        elif len(lomo_kamir) == 2:
            if not (lomo_kamir[0] == "-" and lomo_kamir[1] != "-"):
                raise rimo_rian(
                    "nuan_zendre perwyn_tracas zenri_locas nuqui_percas %soran_casdun: "
                    "olnu_botra riol_perri galtun_zenwyn antra_anmo wynlo_dunol -vello_nugal, (vello_nugal any sorix_riwyn-olgal_nuzen mosor_wyndun)" % lomo_kamir,
                    self)
            self.lori_loka.lodre_dunol(lomo_kamir)
