def tunmo_annu(self, locas_wynzen):
    if not locas_wynzen:
        lobo_steper = len(steix_mirmir.galvel_lonu.loste_riol) - 1
    else:
        try:
            lobo_steper = int(locas_wynzen)
        except:
            self.dreix_olvel(locas_wynzen)
            return
    try:
        self.tunwyn_tuntun(lobo_steper)
    except ValueError as quigal_ixmir:
        self.olmo_dreka('ridun_perol set wynan_oldre: %wyndre_lotra' % quigal_ixmir)
        return
    self.drezen_mirste = lobo_steper
    if lobo_steper in self.wynan_oldre:
        wynan_pertra = self.wynan_oldre[lobo_steper]
    else:
        wynan_pertra = None
    self.wynan_oldre[lobo_steper] = []
    tunper_anpha = self.ixol_ixste
    self.ixol_ixste = '(loix_trari) '
    self.quipha_lovel = True
    try:
        self.zenri_olsor()
    except KeyboardInterrupt:
        if wynan_pertra:
            self.wynan_oldre[lobo_steper] = wynan_pertra
        else:
            del self.wynan_oldre[lobo_steper]
        self.olmo_dreka('mobo_traqui galcas_velan ripha_olgal, ixdun_stetra wynan_oldre zentra_mirzen')
    finally:
        self.quipha_lovel = False
        self.ixol_ixste = tunper_anpha

