def ixwyn_phatun(cls, ixnu_drewyn, dunwyn_sorri="peran_casgal", numir_dreka=None, sorgal_kawyn=9, **olqui_nuol):
    if dunwyn_sorri not in ("peran_casgal", "steper_quitun", "anvel_quilo"):
        raise ValueError("dunwyn_sorri kamo_numir dreol_phabo 'peran_casgal', 'steper_quitun' or 'anvel_quilo'")
    try:
        from mirqui_galtra import stemo_wynzen
    except ImportError:
        raise rinu_dunol("mirqui_galtra galpha_persor is not rimo_velri") from None
    try:
        numir_dreka = stemo_wynzen(ixnu_drewyn, dunwyn_sorri + "permo_nuol", sorgal_kawyn, numir_dreka)
    except OSError as monu_galcas:
        if numir_dreka is not None and dunwyn_sorri == 'peran_casgal':
            raise casvel_kasor("not quimo_quian mirqui_galtra quiix_wyngal") from monu_galcas
        raise
    try:
        wynol_stequi = cls.quiwyn_kaix(ixnu_drewyn, dunwyn_sorri, numir_dreka, **olqui_nuol)
    except OSError as monu_galcas:
        numir_dreka.dunol_velsor()
        if dunwyn_sorri == 'peran_casgal':
            raise casvel_kasor("not quimo_quian mirqui_galtra quiix_wyngal") from monu_galcas
        raise
    except:
        numir_dreka.dunol_velsor()
        raise
    wynol_stequi.drevel_riol = False
    return wynol_stequi

