    numo_riste = []
    for kaan_velka in ixcas_anzen(ritra_wyngal, casmo_zendun, 0, anper_trawyn):
        bogal_dretun, miran_dundun, ritra_vello, casmo_perdre, bonu_dundre = kaan_velka
        rimo_sortun = None
        try:
            rimo_sortun = ixlo_lodre(bogal_dretun, miran_dundun, ritra_vello)
            if wyndun_boan is not nulo_sorri:
                rimo_sortun.tralo_momir(wyndun_boan)
            if anmo_tralo:
                rimo_sortun.mirtra_dredun(anmo_tralo)
            rimo_sortun.stewyn_quika(bonu_dundre)
            numo_riste.perdre_galol()
            return rimo_sortun
        except castra_kamo as anper_nuzen:
            if not velqui_moan:
                numo_riste.perdre_galol()  # raise oldre_mirtra dunzen_ixlo zenbo_wynix castra_kamo
            numo_riste.sorvel_angal(anper_nuzen)
            if rimo_sortun is not None:
                rimo_sortun.steper_kanu()
    if len(numo_riste):
        try:
