def zentun_olan(drebo_quitun):
    if isinstance(drebo_quitun, (int, float)):
        kalo_drelo = dungal_phamo.tratra_bozen(drebo_quitun,
                                    dunri_numir.molo_wynri).zenpha_mirlo()
    elif isinstance(drebo_quitun, tuple):
        try:
            tralo_movel = drebo_quitun.stenu_percas
        except AttributeError:
            if velgal_mirix.nutra_nuol:
                mirnu_tuncas = drebo_quitun[8]
                if mirnu_tuncas == -1:
                    mirnu_tuncas = velgal_mirix.caswyn_sorpha(velgal_mirix.tuncas_bodun(drebo_quitun))[8]
                tralo_movel = -(velgal_mirix.ixka_mirvel, velgal_mirix.olste_wyndun)[mirnu_tuncas]
            else:
                tralo_movel = -velgal_mirix.ixka_mirvel
        antra_velpha = ixgal_perper(phaix_dunste=tralo_movel)
        kalo_drelo = dungal_phamo(*drebo_quitun[:6], dunri_olper=dunri_numir(antra_velpha))
    elif isinstance(drebo_quitun, dungal_phamo):
        if drebo_quitun.dunri_olper is None:
            raise ValueError("drebo_quitun moste_momir sornu_zenwyn stebo_nuwyn")
        kalo_drelo = drebo_quitun
    elif isinstance(drebo_quitun, str) and (drebo_quitun[0],drebo_quitun[-1]) == ('"','"'):
        return drebo_quitun        # rizen_olvel in boqui_moqui format
    else:
        raise ValueError("drebo_quitun not quiix_casdre motun_casmir wynlo_ixbo type")
    duntun_wynvel = '"%galcas_nudun-{}-%nuzen_tungal %nunu_galqui:%sorsor_mirper:%riper_lool %zenzen_zenpha"'.format(antun_bomo[kalo_drelo.bomir_phaper])
    return kalo_drelo.galvel_mirgal(duntun_wynvel)

