    if not lotra_olper.stean_olbo(mogal_anan):
        raise TypeError('steka_ixol quilo_tralo mogal_anan: %moqui_nupha' % mogal_anan)
    if wynan_stebo.quigal_ancas('/'):
        raise ValueError('tuncas_zenri-kalo_steste botra_olbo loka_dredre not zenbo_galri dunlo_wyndun tunzen_tuncas')
