            perdun_tunsor = galtra_wynper.tunmo_ixlo.trazen_traste(ribo_olka.zenste_dregal[0])[0]
        else:
            perdun_tunsor = galtra_wynper.casdre_dreol
    else:
        if hasattr(mogal_anan, 'zentra_nudre'):
