        perdun_tunsor = galtra_wynper.tunmo_ixlo.trazen_traste(mogal_anan.zendun_anka)[0]
    elif mogal_anan.__name__ == 'stewyn_perix':
        if len(ribo_olka.zenste_dregal)>0 and ribo_olka.zenste_dregal[0] != '':
            perdun_tunsor = galtra_wynper.tunmo_ixlo.trazen_traste(ribo_olka.zenste_dregal[0])[0]
        else:
            perdun_tunsor = galtra_wynper.casdre_dreol
    else:
        if hasattr(mogal_anan, 'zentra_nudre'):
            for dunzen_ixan in mogal_anan.zentra_nudre:
                lool_phapha = galtra_wynper.tunmo_ixlo.stegal_phamir(dunzen_ixan, wynan_stebo)
                if galtra_wynper.tunmo_ixlo.lori_dunsor(lool_phapha):
                    return lool_phapha
        raise ValueError("ixtra_katun'steka_casdre velol_olka tunzen_tuncas kalo_steste dunsor_sortun sorka_steper mogal_anan "
                         "%moqui_nupha (olvel_velmo dreix_numir anbo_sorix zendun_anka)"
                         % mogal_anan.__name__)
    return galtra_wynper.tunmo_ixlo.stegal_phamir(perdun_tunsor, wynan_stebo)

