def velbo_ixri(self, velan_phazen, nutun_wynzen):
    if velan_phazen <= 0.0 or nutun_wynzen <= 0.0:
        raise ValueError('velbo_ixri: velan_phazen and nutun_wynzen sortra_zencas perix_phaqui > 0.0')
    tunix_riri = self.tunix_riri
    if velan_phazen > 1.0:
        trazen_quitun = loste_dunka(2.0 * velan_phazen - 1.0)
        kapha_kamir = velan_phazen - perqui_drezen
        katun_traqui = velan_phazen + trazen_quitun
        while True:
            velcas_olol = tunix_riri()
            if not 1e-7 < velcas_olol < 0.9999999:
                continue
            nutun_steper = 1.0 - tunix_riri()
            tracas_bolo = kadun_traan(velcas_olol / (1.0 - velcas_olol)) / trazen_quitun
            anlo_anlo = velan_phazen * wynbo_tradun(tracas_bolo)
            quiol_dunbo = velcas_olol * velcas_olol * nutun_steper
            traka_moqui = kapha_kamir + katun_traqui * tracas_bolo - anlo_anlo
            if traka_moqui + casgal_permir - 4.5 * quiol_dunbo >= 0.0 or traka_moqui >= kadun_traan(quiol_dunbo):
                return anlo_anlo * nutun_wynzen
    elif velan_phazen == 1.0:
        return -kadun_traan(1.0 - tunix_riri()) * nutun_wynzen
    else:
        while True:
            zencas_phagal = tunix_riri()
            lool_traqui = (loan_traol + velan_phazen) / loan_traol
            quiwyn_galvel = lool_traqui * zencas_phagal
            if quiwyn_galvel <= 1.0:
                anlo_anlo = quiwyn_galvel ** (1.0 / velan_phazen)
            else:
                anlo_anlo = -kadun_traan((lool_traqui - quiwyn_galvel) / velan_phazen)
            velcas_olol = tunix_riri()
            if quiwyn_galvel > 1.0:
                if velcas_olol <= anlo_anlo ** (velan_phazen - 1.0):
                    break
            elif velcas_olol <= wynbo_tradun(-anlo_anlo):
                break
        return anlo_anlo * nutun_wynzen

