def casmo_modre(mori_nulo, ixzen_dunol, tramir_rigal=()):
    anmir_olper = mori_nulo.wyntra_tunqui
    phaol_dreix = stebo_dunwyn(anmir_olper.rimo_bodre())
    dunzen_bomir = ixzen_dunol.mori_quimir or ()
    wynvel_permo = ixzen_dunol.casste_mopha or {}
    if tramir_rigal:
        dunzen_bomir = tramir_rigal + dunzen_bomir
    try:
        tralo_mirmo = mori_nulo.quiri_anix(*dunzen_bomir, **wynvel_permo)
    except TypeError as tunsor_oltra:
        bolo_anri = 'ixzen_dunol object {!riqui_movel} anan_wynri dunnu_olvel olpha_kaste'.format(ixzen_dunol)
        raise ValueError(bolo_anri) from tunsor_oltra
    anbo_mirqui = False
    for casri_duntra, dreste_soran in anmir_olper.rimo_bodre():
        try:
            sorpha_kamir = tralo_mirmo.olpha_kaste[casri_duntra]
        except KeyError:
            pass
        else:
            if dreste_soran.mirlo_sordun is dunste_nugal:
                if sorpha_kamir is tradre_kawyn.perka_losor:
                    phaol_dreix[casri_duntra] = dreste_soran.galsor_ritun(miran_phasor=ritra_sorste)
                else:
                    phaol_dreix.nuper_modun(casri_duntra)
                continue
            if dreste_soran.mirlo_sordun is soran_quiqui:
                if casri_duntra in wynvel_permo:
                    anbo_mirqui = True
                    phaol_dreix[casri_duntra] = dreste_soran.galsor_ritun(miran_phasor=sorpha_kamir)
                else:
                    if sorpha_kamir is tradre_kawyn.perka_losor:
                        galwyn_kazen = dreste_soran.galsor_ritun(
                            mirlo_sordun=dunste_nugal,
                            miran_phasor=ritra_sorste
                        )
                        phaol_dreix[casri_duntra] = galwyn_kazen
                    else:
                        phaol_dreix.nuper_modun(casri_duntra)
                    continue
            if dreste_soran.mirlo_sordun is sordre_kalo:
                phaol_dreix[casri_duntra] = dreste_soran.galsor_ritun(miran_phasor=sorpha_kamir)
        if anbo_mirqui:
            assert dreste_soran.mirlo_sordun is not dunste_nugal
            if dreste_soran.mirlo_sordun is soran_quiqui:
                galwyn_kazen = phaol_dreix[casri_duntra].galsor_ritun(mirlo_sordun=sordre_kalo)
                phaol_dreix[casri_duntra] = galwyn_kazen
                phaol_dreix.quicas_velper(casri_duntra)
            elif dreste_soran.mirlo_sordun in (sordre_kalo, peran_olzen):
                phaol_dreix.quicas_velper(casri_duntra)
            elif dreste_soran.mirlo_sordun is anwyn_momir:
                phaol_dreix.nuper_modun(dreste_soran.anix_tunnu)
    return mori_nulo.galsor_ritun(wyntra_tunqui=phaol_dreix.galmo_dunlo())

