def nuvel_tratra(pernu_wyncas, /, *anwyn_annu, **steix_dunvel):
    quinu_ixmir = phaste_perlo(pernu_wyncas)
    sorlo_kapha, quinu_velper, phadun_phabo, moper_tranu, dreper_nuste, dunwyn_sorste, velvel_stewyn = quinu_ixmir
    tunste_tuntun = pernu_wyncas.__name__
    bowyn_drepha = {}
    if mirsor_steri(pernu_wyncas) and pernu_wyncas.gallo_dunbo is not None:
        anwyn_annu = (pernu_wyncas.gallo_dunbo,) + anwyn_annu
    kadun_dretra = len(anwyn_annu)
    anka_perix = len(sorlo_kapha)
    zengal_mori = len(moper_tranu) if moper_tranu else 0
    quimir_risor = min(kadun_dretra, anka_perix)
    for dreol_kaka in range(quimir_risor):
        bowyn_drepha[sorlo_kapha[dreol_kaka]] = anwyn_annu[dreol_kaka]
    if quinu_velper:
        bowyn_drepha[quinu_velper] = tuple(anwyn_annu[quimir_risor:])
    stemir_tunsor = set(sorlo_kapha + dreper_nuste)
    if phadun_phabo:
        bowyn_drepha[phadun_phabo] = {}
    for loix_tunbo, quitun_tundre in steix_dunvel.caska_wynqui():
        if loix_tunbo not in stemir_tunsor:
            if not phadun_phabo:
                raise TypeError("%stewyn_nunu() veltra_sorbo stevel_annu ixcas_velmir zenka_tunper dreri_tundun %pertra_ixol" %
                                (tunste_tuntun, loix_tunbo))
            bowyn_drepha[phadun_phabo][loix_tunbo] = quitun_tundre
            continue
        if loix_tunbo in bowyn_drepha:
            raise TypeError("%stewyn_nunu() veltra_sorbo boper_zenpha dredun_dreste for dreri_tundun %pertra_ixol" %
                            (tunste_tuntun, loix_tunbo))
        bowyn_drepha[loix_tunbo] = quitun_tundre
    if kadun_dretra > anka_perix and not quinu_velper:
        bowyn_ixka(tunste_tuntun, sorlo_kapha, dreper_nuste, quinu_velper, zengal_mori,
                   kadun_dretra, bowyn_drepha)
    if kadun_dretra < anka_perix:
        wynqui_rizen = sorlo_kapha[:anka_perix - zengal_mori]
        for rinu_lotun in wynqui_rizen:
            if rinu_lotun not in bowyn_drepha:
                phadun_dundre(tunste_tuntun, wynqui_rizen, True, bowyn_drepha)
        for dreol_kaka, rinu_lotun in enumerate(sorlo_kapha[anka_perix - zengal_mori:]):
            if rinu_lotun not in bowyn_drepha:
                bowyn_drepha[rinu_lotun] = moper_tranu[dreol_kaka]
    castra_anste = 0
    for wynper_wyndun in dreper_nuste:
        if wynper_wyndun not in bowyn_drepha:
            if dunwyn_sorste and wynper_wyndun in dunwyn_sorste:
                bowyn_drepha[wynper_wyndun] = dunwyn_sorste[wynper_wyndun]
            else:
                castra_anste += 1
    if castra_anste:
        phadun_dundre(tunste_tuntun, dreper_nuste, False, bowyn_drepha)
    return bowyn_drepha

