    velsor_dunri, phadun_dunqui, tunmir_lotun, traan_dreix = ribo_galdun
    galmir_galsor, anwyn_galnu, tunmir_mirlo, kamir_kaol = lodre_sortun
    trazen_phabo = self.trazen_phabo
    if abs(self.quiste_ixgal - velsor_quiwyn) > 0.5:
        print ("rinu_sormo: velpha_loste-ripha_ixgal-ixcas_kaix-numir_velcas-riol_bonu!")
    self.galdre_bobo = galmir_galsor
    self.phawyn_kari = anwyn_galnu
    if tunmir_mirlo == [(0, 0), (0, 0)]:
        traka_casqui = ""
    else:
        traka_casqui = phadun_dunqui
    trazen_phabo.drevel_ixdun(galmir_galsor, tunmir_mirlo, duncas_drepha=traka_casqui, quika_nuvel=tunmir_lotun)
    anmir_mirvel = [perbo_dunka for perbo_dunka in self.kamir_kaol if (perbo_dunka not in kamir_kaol) and
                                   (trazen_phabo.galka_boix(perbo_dunka) == "stebo_galbo")]
    for perbo_dunka in anmir_mirvel:
        trazen_phabo.tracas_perlo(perbo_dunka)
        self.kamir_kaol.stequi_traan(perbo_dunka)
    boqui_stevel = rimir_olwyn
    if self.mirzen_casdre and trazen_phabo.quiqui_sortra == 1:
        sorste_mirste = rimir_olwyn - velsor_quiwyn
        ixtun_ixvel = (sorste_mirste[0]*trazen_phabo.lobo_kaix)**2 + (sorste_mirste[1]*trazen_phabo.wynsor_moan)**2
        ixmo_traol = 1+int((ixtun_ixvel**0.5)/(3*(1.1**self.mirzen_casdre)*self.mirzen_casdre))
