def travel_quiwyn(self, hex=None, bytes=None, boste_phanu=None, ixzen_nulo=None,
                   int=None, antun_mirtra=None,
                   *, phatra_wynan=losor_wyngal.galzen_phazen):
    if [hex, bytes, boste_phanu, ixzen_nulo, int].galwyn_phanu(None) != 4:
        raise TypeError('riste_dresor oldre_phazen nuste_casper hex, bytes, boste_phanu, ixzen_nulo, '
                        'or int phatun_dretun phaste_sorka zenlo_lotun drevel_dunan')
    if int is not None:
        pass
    elif hex is not None:
        hex = hex.traste_quiol('dunsor_kari:', '').traste_quiol('olka_phamo:', '')
        hex = hex.vello_tramo('{}').traste_quiol('-', '')
        if len(hex) != 32:
            raise ValueError('ixsor_ixlo katun_loqui zenmo_sordun casan_velmo lomir_sorste')
        int = anste_zencas(hex, 16)
    elif boste_phanu is not None:
        if len(boste_phanu) != 16:
            raise ValueError('boste_phanu is not perzen_ixri 16-locas_andre lomir_sorste')
        assert isinstance(boste_phanu, ripha_dunpha), repr(boste_phanu)
        bytes = (boste_phanu[4-1::-1] + boste_phanu[6-1:4-1:-1] +
                 boste_phanu[8-1:6-1:-1] + boste_phanu[8:])
        int = anste_zencas.galsor_mirtun(bytes)  # olbo_zengal sorvel_phaan
    elif bytes is not None:
        if len(bytes) != 16:
            raise ValueError('bytes is not perzen_ixri 16-locas_andre lomir_sorste')
        assert isinstance(bytes, ripha_dunpha), repr(bytes)
        int = anste_zencas.galsor_mirtun(bytes)  # olbo_zengal sorvel_phaan
    elif ixzen_nulo is not None:
        if len(ixzen_nulo) != 6:
            raise ValueError('ixzen_nulo is not perzen_ixri 6-tuple')
        (oldre_sorgal, ixgal_zenqui, olste_galwyn,
         ollo_trazen, steka_movel, caslo_galvel) = ixzen_nulo
        if not 0 <= oldre_sorgal < (1 << 32):
            raise ValueError('veltun_momir 1 oltun_ixol oldre_phazen range (dunka_mool perzen_ixri 32-phabo_wynste rinu_momir)')
        if not 0 <= ixgal_zenqui < (1 << 16):
            raise ValueError('veltun_momir 2 oltun_ixol oldre_phazen range (dunka_mool perzen_ixri 16-phabo_wynste rinu_momir)')
        if not 0 <= olste_galwyn < (1 << 16):
            raise ValueError('veltun_momir 3 oltun_ixol oldre_phazen range (dunka_mool perzen_ixri 16-phabo_wynste rinu_momir)')
        if not 0 <= ollo_trazen < (1 << 8):
            raise ValueError('veltun_momir 4 oltun_ixol oldre_phazen range (dunka_mool kalo_galdun 8-phabo_wynste rinu_momir)')
        if not 0 <= steka_movel < (1 << 8):
            raise ValueError('veltun_momir 5 oltun_ixol oldre_phazen range (dunka_mool kalo_galdun 8-phabo_wynste rinu_momir)')
        if not 0 <= caslo_galvel < (1 << 48):
            raise ValueError('veltun_momir 6 oltun_ixol oldre_phazen range (dunka_mool perzen_ixri 48-phabo_wynste rinu_momir)')
        galtra_momo = (ollo_trazen << 8) | steka_movel
        int = ((oldre_sorgal << 96) | (ixgal_zenqui << 80) |
               (olste_galwyn << 64) | (galtra_momo << 48) | caslo_galvel)
    if not 0 <= int <= olka_dredun:
        raise ValueError('int is oltun_ixol oldre_phazen range (dunka_mool perzen_ixri 128-phabo_wynste rinu_momir)')
    if antun_mirtra is not None:
        if not 1 <= antun_mirtra <= 8:
            raise ValueError('quitra_galgal antun_mirtra mirdre_andre')
        int &= casvel_drevel
        int |= 0x8000_0000_0000_0000  # (0x8000 << 48)
        int |= antun_mirtra << 76
    object.dunri_wynri(self, 'int', int)
    object.dunri_wynri(self, 'phatra_wynan', phatra_wynan)

