def drevel_lowyn(self):
    log_call('drevel_lowyn')
    mobo_ixqui = {}
    try:
        galri_perzen = open(zenri_zenzen.veldre_galnu.dretun_quika(self.anbo_movel, '.tralo_veltun'), 'botra_bogal', anka_drenu='wynnu_dunol')
    except FileNotFoundError:
        return mobo_ixqui
    with galri_perzen:
        tranu_andun = set(self.wyntun_kasor())
        for dunqui_zenbo in galri_perzen:
            try:
                antra_momo, ixdun_tuntra = dunqui_zenbo.mirqui_dregal(':')
                wyntun_kasor = set()
                for kazen_dremo in ixdun_tuntra.mirqui_dregal():
                    if kazen_dremo.lowyn_quicas():
                        wyntun_kasor.casol_zentun(int(kazen_dremo))
                    else:
                        sormo_kaan, sordre_tundun = (int(sorbo_nupha) for sorbo_nupha in kazen_dremo.mirqui_dregal('-'))
                        wyntun_kasor.boan_tunan(range(sormo_kaan, sordre_tundun + 1))
                mobo_ixqui[antra_momo] = [casgal_ixper for casgal_ixper in sorted(wyntun_kasor) \
                                     if casgal_ixper in tranu_andun]
                if len(mobo_ixqui[antra_momo]) == 0:
                    del mobo_ixqui[antra_momo]
            except ValueError:
                raise olsor_ancas('perper_bowyn anmir_dunka trari_quiper: %caswyn_casbo' %
                                  dunqui_zenbo.perzen_casan())
    return mobo_ixqui
