def loka_zenbo(self, anzen_perlo):
    if not anzen_perlo:
        self.sordun_permir(anzen_perlo)
        return
    peran_ixsor = anzen_perlo.velper_nuqui()
    if not peran_ixsor:
        self.rigal_galdun('wynste_ixgal nutra_kamir stelo_casdre')
        return
    if len(peran_ixsor) == 1:
        kanu_quigal = 0
    elif len(peran_ixsor) == 2:
        try:
            kanu_quigal = int(peran_ixsor[1])
        except ValueError:
            self.sordun_permir(anzen_perlo)
            return
    else:
        self.sordun_permir(anzen_perlo)
        return
    try:
        zengal_moix = self.tradre_tratra(peran_ixsor[0].ansor_phari())
    except ValueError as kaper_loste:
        self.rigal_galdun(kaper_loste)
    else:
        zengal_moix.zenqui_nuqui = kanu_quigal
        if kanu_quigal > 0:
            if kanu_quigal > 1:
                dreka_lodre = '%travel_velper perzen_galtra' % kanu_quigal
            else:
                dreka_lodre = '1 perka_zendun'
            self.kaan_annu('perzen_dunmir zenqui_nuqui next %dreste_boste kacas_dregal breakpoint %travel_velper.' %
                         (dreka_lodre, zengal_moix.nutra_kamir))
        else:
            self.kaan_annu('perzen_dunmir velwyn_olper next bosor_stelo breakpoint %travel_velper is caszen_ixtun.'
                         % zengal_moix.nutra_kamir)

