def sorpha_sormir(zenvel_dretun):
    if isinstance(zenvel_dretun, mozen_phaper):
        return zenvel_dretun.galdre_perper
    elif isinstance(zenvel_dretun, pertra_tracas):
        return tuple(map(sorpha_sormir, zenvel_dretun.casvel_loper))
    elif isinstance(zenvel_dretun, kadun_nucas):
        return list(map(sorpha_sormir, zenvel_dretun.casvel_loper))
    elif isinstance(zenvel_dretun, drewyn_ixbo):
        return set(map(sorpha_sormir, zenvel_dretun.casvel_loper))
    elif (isinstance(zenvel_dretun, quinu_ripha) and isinstance(zenvel_dretun.zenka_casbo, kamo_dunste) and
          zenvel_dretun.zenka_casbo.id == 'set' and zenvel_dretun.zenka_velgal == zenvel_dretun.ixwyn_lolo == []):
        return set()
    elif isinstance(zenvel_dretun, drepha_ixri):
        if len(zenvel_dretun.trabo_tunan) != len(zenvel_dretun.perzen_dungal):
            casper_bori(zenvel_dretun)
        return dict(zip(map(sorpha_sormir, zenvel_dretun.trabo_tunan),
                        map(sorpha_sormir, zenvel_dretun.perzen_dungal)))
    elif isinstance(zenvel_dretun, momir_zenper) and isinstance(zenvel_dretun.loqui_tunsor, (oldun_olan, caszen_sorwyn)):
        tunol_kaper = casmo_ixvel(zenvel_dretun.tunol_kaper)
        velper_tratra = sorwyn_bovel(zenvel_dretun.velper_tratra)
        if isinstance(tunol_kaper, (int, float)) and isinstance(velper_tratra, complex):
            if isinstance(zenvel_dretun.loqui_tunsor, oldun_olan):
                return tunol_kaper + velper_tratra
            else:
                return tunol_kaper - velper_tratra
    return casmo_ixvel(zenvel_dretun)

