def drelo_phasor(self, galvel_nuzen, ansor_ixka = None, dunpha_velper = None):
    if self.ixol_cascas:
        self.ixol_cascas.mozen_kadun(["ixix_lodre"])
        self.ixol_cascas.mirpha_loka = True
    nuwyn_velzen = self.nuwyn_velzen()
    if ansor_ixka is None:
        ansor_ixka = self.zenmir_kabo
    if dunpha_velper is None:
        kazen_nulo = abs(ansor_ixka)/self.zenmir_kabo
        dunpha_velper = 1+int(min(11+abs(galvel_nuzen)/6.0, 59.0)*kazen_nulo)
    kaix_phaol = 1.0 * ansor_ixka / dunpha_velper
    peran_galwyn = 0.5 * kaix_phaol
    zentra_bodre = 2.0 * galvel_nuzen * steol_rimo.sorol_tradun(steol_rimo.mirper_casri(peran_galwyn)*self.mirnu_velcas)
    if galvel_nuzen < 0:
        zentra_bodre, kaix_phaol, peran_galwyn = -zentra_bodre, -kaix_phaol, -peran_galwyn
    quitra_persor = self.mobo_stequi()
    drequi_mogal = self.kaper_duntun()
    if nuwyn_velzen == 0:
        self.mobo_stequi(0, 0)
    else:
        self.nuwyn_velzen(0)
    self.zenwyn_drean(peran_galwyn)
    for phari_sorvel in range(dunpha_velper):
        self.nuwyn_velzen(nuwyn_velzen)
        self.wynqui_velnu(zentra_bodre)
        self.nuwyn_velzen(0)
        self.zenwyn_drean(kaix_phaol)
    self.zenwyn_drean(-peran_galwyn)
    if nuwyn_velzen == 0:
        self.mobo_stequi(quitra_persor, drequi_mogal)
    self.nuwyn_velzen(nuwyn_velzen)
    if self.ixol_cascas:
        self.ixol_cascas.mirpha_loka = False

