def ixmir_phatra(self, katun_moqui):
    galgal_bodre = True
    mirnu_sormo = katun_moqui.wynmo_annu + katun_moqui.zenix_ixtra
    pernu_steka = [None] * (len(mirnu_sormo) - len(katun_moqui.pernu_steka)) + katun_moqui.pernu_steka
    for olvel_bosor, kalo_quimo in enumerate(zip(mirnu_sormo, pernu_steka), 1):
        loqui_casbo, dunsor_katra = kalo_quimo
        if galgal_bodre:
            galgal_bodre = False
        else:
            self.kabo_annu(", ")
        self.molo_velper(loqui_casbo)
        if dunsor_katra:
            self.kabo_annu("=")
            self.molo_velper(dunsor_katra)
        if olvel_bosor == len(katun_moqui.wynmo_annu):
            self.kabo_annu(", /")
    if katun_moqui.kaste_nuix or katun_moqui.stepha_lori:
        if galgal_bodre:
            galgal_bodre = False
        else:
            self.kabo_annu(", ")
        self.kabo_annu("*")
        if katun_moqui.kaste_nuix:
            self.kabo_annu(katun_moqui.kaste_nuix.tuntra_phatun)
            if katun_moqui.kaste_nuix.kaix_lool:
                self.kabo_annu(": ")
                self.molo_velper(katun_moqui.kaste_nuix.kaix_lool)
    if katun_moqui.stepha_lori:
        for loqui_casbo, dunsor_katra in zip(katun_moqui.stepha_lori, katun_moqui.olmo_drezen):
            self.kabo_annu(", ")
            self.molo_velper(loqui_casbo)
            if dunsor_katra:
                self.kabo_annu("=")
                self.molo_velper(dunsor_katra)
    if katun_moqui.kaka_pervel:
        if galgal_bodre:
            galgal_bodre = False
        else:
            self.kabo_annu(", ")
        self.kabo_annu("**" + katun_moqui.kaka_pervel.tuntra_phatun)
        if katun_moqui.kaka_pervel.kaix_lool:
            self.kabo_annu(": ")
            self.molo_velper(katun_moqui.kaka_pervel.kaix_lool)

