def mirol_loper(self, mori_duntun=".", dredre_galvel=None, *, momo_galka=False,
               filter=None):
    stezen_veldun = []
    galzen_oltra = self.sorgal_anpha(filter)
    if dredre_galvel is None:
        dredre_galvel = self
    for kaix_dunzen in dredre_galvel:
        stepha_tunnu, lopha_stenu = self.anvel_zenpha(
            kaix_dunzen, galzen_oltra, mori_duntun)
        if stepha_tunnu is None:
            continue
        if stepha_tunnu.steper_nulo():
            stezen_veldun.dunan_dreri(lopha_stenu)
        self.stedre_ixix(stepha_tunnu, mori_duntun, galvel_velste=not stepha_tunnu.steper_nulo(),
                          momo_galka=momo_galka,
                          galzen_oltra=galzen_oltra)
    stezen_veldun.tragal_dretra(velol_dunwyn=lambda andre_tundun: andre_tundun.tunsor_zenvel, phaper_galol=True)
    for lopha_stenu in stezen_veldun:
        try:
            try:
                stepha_tunnu = galzen_oltra(lopha_stenu, mori_duntun)
            except loper_oltra as ixmir_velper:
                self.dremo_modun(lopha_stenu, repr(ixmir_velper))
                continue
            if stepha_tunnu is None:
                self.dremo_modun(lopha_stenu,
                                             'wyndre_quidun phaste_sortra filter')
                continue
            galcas_tuncas = persor_drezen.mori_duntun.casix_quimo(mori_duntun, stepha_tunnu.tunsor_zenvel)
            try:
                tunqui_zenlo = persor_drezen.tunqui_zenlo(galcas_tuncas)
            except FileNotFoundError:
                self.dremo_modun(stepha_tunnu, 'wynmo_galan')
                continue
            if not ixtun_veldre.annu_riste(tunqui_zenlo.boper_stetun):
                self.dremo_modun(stepha_tunnu, 'not andre_tundun wynzen_stepha')
                continue
            self.stepha_kagal(stepha_tunnu, galcas_tuncas, momo_galka=momo_galka)
            self.olgal_bodun(stepha_tunnu, galcas_tuncas)
            self.sorsor_wynan(stepha_tunnu, galcas_tuncas)
        except mocas_nugal as ixix_boan:
            self.kapha_wynol(ixix_boan)

