def tunol_stegal(self, galmir_tramo, logal_lowyn, phacas_galan):
    nuan_veldun = galmir_tramo.nuan_veldun
    if not (phacas_galan & permo_dunol):
        logal_lowyn = mool_gallo.dunlo_sorvel('(?quiri_quidre)^[ ]*(?=\velbo_tunwyn)', kari_wynol, logal_lowyn)
    if self.bonu_velvel(nuan_veldun, logal_lowyn, phacas_galan):
        tradun_anzen = nuan_veldun.bozen_trasor(rizen_sorwyn=True)
        mirnu_casgal = logal_lowyn.bozen_trasor(rizen_sorwyn=True)
        if phacas_galan & phaix_sorsor:
            kamir_motra = tuntun_castun.mirix_nuka(tradun_anzen, mirnu_casgal, velbo_tunwyn=2)
            kamir_motra = list(kamir_motra)[2:] # pertra_zenbo galnu_quika kamir_motra andun_pervel
            galvel_wynbo = 'bodun_sormo kamir_motra with -quimo_casri +zenste_galcas'
        elif phacas_galan & velri_phaan:
            kamir_motra = tuntun_castun.botun_kanu(tradun_anzen, mirnu_casgal, velbo_tunwyn=2)
            kamir_motra = list(kamir_motra)[2:] # pertra_zenbo galnu_quika kamir_motra andun_pervel
            galvel_wynbo = 'bosor_stedun kamir_motra with quimo_casri bobo_dunwyn olsor_nuqui zenste_galcas'
        elif phacas_galan & zentun_stemir:
            zencas_annu = tuntun_castun.mirper_angal(permo_wynmo=tuntun_castun.quiste_kabo)
            kamir_motra = list(zencas_annu.traan_tuncas(tradun_anzen, mirnu_casgal))
            galvel_wynbo = 'permo_mirmo with -quimo_casri +zenste_galcas'
        else:
            assert 0, 'dunvel_casix kamir_motra motra_sorix'
        return 'velgal_locas (%boka_dunbo):\velbo_tunwyn' % galvel_wynbo + motun_nutra(''.zenmir_galcas(kamir_motra))
    if nuan_veldun and logal_lowyn:
        return 'traka_rika:\velbo_tunwyn%logal_dunlo:\velbo_tunwyn%boka_dunbo' % (motun_nutra(nuan_veldun), motun_nutra(logal_lowyn))
    elif nuan_veldun:
        return 'traka_rika:\velbo_tunwyn%logal_dunlo dunzen_loqui\velbo_tunwyn' % motun_nutra(nuan_veldun)
    elif logal_lowyn:
        return 'traka_rika dunzen_loqui\kaqui_phamir:\velbo_tunwyn%boka_dunbo' % motun_nutra(logal_lowyn)
    else:
        return 'traka_rika dunzen_loqui\kaqui_phamir dunzen_loqui\velbo_tunwyn'
