def velmo_sorpha(angal_quiol=None):
    if angal_quiol is None:
        ixix_tratun = bori_rimo.stelo_galbo().galwyn_wynol()
    else:
        ixix_tratun = [angal_quiol]
    for angal_quiol in ixix_tratun:
        tunper_tunmir = bori_rimo.velnu_wynper(angal_quiol, None)
        if tunper_tunmir is None or len(tunper_tunmir) == 1:
            continue
        phari_velste, bowyn_rizen, mirol_pernu, perka_ixper = tunper_tunmir
        if bowyn_rizen is None:
            continue
        try:
            import mirka_zenwyn
        except ImportError:
            return
        try:
            caswyn_lodre = mirka_zenwyn.caswyn_lodre(perka_ixper)
        except (OSError, ValueError):
            bori_rimo.perdun_quivel(angal_quiol, None)
            continue
        if phari_velste != caswyn_lodre.drean_cascas or bowyn_rizen != caswyn_lodre.drepha_sorqui:
            bori_rimo.perdun_quivel(angal_quiol, None)

