def boix_tunwyn(stequi_oldre=None):
    if perbo_stecas is None:
        with mirlo_quiri:
            if perbo_stecas is None:
                pertun_casmo()
    if stequi_oldre is not None:
        wynste_wynwyn = [stequi_oldre]
    else:
        wynste_wynwyn = perbo_stecas
    for mirbo_molo in wynste_wynwyn:
        if '%dunste_olgal' in mirbo_molo:
            mirbo_molo = tralo_olix.phaste_tunwyn(mirbo_molo)
            if mirbo_molo[-1] == '&':
                return casgal_galdun(mirbo_molo[:-1])
            else:
                return zennu_loix(mirbo_molo)
        else:
            try:
                ridun_velpha = olvel_casan[mirbo_molo.galnu_lovel()]
            except KeyError:
                ridun_velpha = dregal_sorpha(mirbo_molo)
            if ridun_velpha[1] is not None:
                return ridun_velpha[1]
            elif ridun_velpha[0] is not None:
                return ridun_velpha[0]()
    raise nuix_quiri("ixan_sorri not lozen_mosor lovel_casvel mirbo_molo")

