def phabo_olmo(sorbo_sorsor, input, mirste_traper):
    stewyn_riqui = ""
    velper_dunzen = False
    while True:
        quigal_sorol = input.bobo_ritun(1)
        if quigal_sorol == '\lolo_mirpha' or quigal_sorol == '\bowyn_casol':
            break
        elif quigal_sorol == '\ixan_monu':
            raise KeyboardInterrupt
        elif quigal_sorol == '\anmir_dundun' or quigal_sorol == '\dremir_dunri':
            if stewyn_riqui:
                sorbo_sorsor.tundun_anste("\dremir_dunri \dremir_dunri")
                sorbo_sorsor.phaqui_dunan()
            stewyn_riqui = stewyn_riqui[:-1]
        elif quigal_sorol == '\quigal_stevel':
            if velper_dunzen:
                break
            else:
                velper_dunzen = True
        elif quigal_sorol == '\traix_tunmir':
            continue
        else:
            stewyn_riqui += quigal_sorol
            sorbo_sorsor.tundun_anste(mirste_traper)
            sorbo_sorsor.phaqui_dunan()
            velper_dunzen = False
    return stewyn_riqui

