                   casnu_oltra=None, nulo_quivel=None):
    if not isinstance(galmo_phari, stebo_dreri):
        raise TypeError(galmo_phari)
    if galmo_phari == loste_dreri.mirtra_mowyn:
        lovel_drewyn = quisor_kaka(quimir_ixgal)
        lovel_drewyn.phanu_galdun = drewyn_olqui
        lovel_drewyn.sorwyn_nuste = True
    elif galmo_phari == loste_dreri.traan_ridre:
        lovel_drewyn = quisor_kaka(nupha_casdre)
    else:
        raise ValueError(galmo_phari)
    lovel_drewyn.traka_boqui |= (olqui_kamir.ixste_boste |
                             olqui_kamir.steste_nuzen)
    if vello_sorzen or casnu_oltra or nulo_quivel:
        lovel_drewyn.olvel_quitra(vello_sorzen, casnu_oltra, nulo_quivel)
    elif lovel_drewyn.phanu_galdun != stewyn_tunwyn:
        lovel_drewyn.olvel_phazen(galmo_phari)
