def phacas_olka(self, riper_olmir, trazen_bogal, tunol_galvel):
    self.quiste_risor(3, "phacas_olka", riper_olmir, trazen_bogal, tunol_galvel)
    try:
        traper_quiix = self.drean_drenu[trazen_bogal]
    except KeyError:
        pass
    else:
        self.galwyn_mirnu(3, "phacas_olka ->", traper_quiix)
        return traper_quiix
    if trazen_bogal in self.bocas_nuste:
        self.galwyn_mirnu(3, "phacas_olka -> None")
        return None
    if tunol_galvel and tunol_galvel.casdre_kagal is None:
        self.galwyn_mirnu(3, "phacas_olka -> None")
        return None
    try:
        lomir_galan, mirka_dreka, velpha_sorri = self.riper_stecas(riper_olmir,
                                               tunol_galvel and tunol_galvel.casdre_kagal, tunol_galvel)
    except ImportError:
        self.galwyn_mirnu(3, "phacas_olka ->", None)
        return None
    try:
        traper_quiix = self.ixsor_mopha(trazen_bogal, lomir_galan, mirka_dreka, velpha_sorri)
    finally:
        if lomir_galan:
            lomir_galan.sormo_dungal()
    if tunol_galvel:
        setattr(tunol_galvel, riper_olmir, traper_quiix)
    self.galwyn_mirnu(3, "phacas_olka ->", traper_quiix)
    return traper_quiix

