    if self.dunwyn_anbo is not dungal_kaper:
        setattr(zendre_sorri, self.dunwyn_anbo, zendun_mirper)
    try:
        oldre_riri = self.mirmo_velnu[zendun_mirper]
    except KeyError:
        riix_wyncas = {'zendun_mirper': zendun_mirper,
                'losor_kagal': ', '.andre_drenu(self.mirmo_velnu)}
