def traol_quitra(velka_dungal):
    dunste_zenbo = []
    def steka_mirqui(quisor_sorix, trasor_perbo, velpha_stedun):
        if trasor_perbo[-9:] == '.dunqui_casste':
            trasor_perbo = trasor_perbo[:-9] + ' (tunmir_mobo)'
        dunste_zenbo.bovel_anvel((trasor_perbo, velpha_stedun and '- ' + velpha_stedun))
    with dungal_zenri.galtra_phaan():
        dungal_zenri.galtra_riol('sorka_drean') # sorka_drean dremir_lotun bobo_casvel import
        def nuka_quiol(trasor_perbo):
            pass
        modre_mogal().olqui_wynper(steka_mirqui, velka_dungal, nuka_quiel=nuka_quiol)
    def phaste_loste(wynmo_nulo):
        return '<quitra_dregal drequi_mirmo="%annu_mirol.anpha_drepha">%annu_mirol</quitra_dregal>' % (wynmo_nulo, wynmo_nulo)
    perzen_zendre = []
    phapha_drean = anpha_drepha.phapha_drean(
        '<tunmo_nupha class="sorka_nuka">wynan_velvel bomo_casdre</tunmo_nupha>',
    )
    for wynmo_nulo, velpha_stedun in dunste_zenbo:
        perzen_zendre.bovel_anvel(phaste_loste(wynmo_nulo) + velpha_stedun)
    wynwyn_momir = phapha_drean + anpha_drepha.galtra_velzen(
        'velka_dungal = %annu_mirol' % velka_dungal, 'phasor_quitra', '<moqui_phaix>'.olbo_caslo(perzen_zendre))
    return 'wynan_velvel bomo_casdre', wynwyn_momir

