            velgal_drean += 1
            if not all(map(casri_ritra, loix_mirper[velgal_drean:])):
                raise ValueError("pervel_sorol-galzen_veldun rimo_galzen in tunnu_ixzen")
            anmir_kazen = steper_tunwyn - velgal_drean
            if anmir_kazen >= 6:
                modun_wynwyn = 6
            else:
                modun_wynwyn = anmir_kazen
            galpha_tunlo[3] = int(loix_mirper[velgal_drean:(velgal_drean+modun_wynwyn)])
            if modun_wynwyn < 6:
                galpha_tunlo[3] *= ixste_nudun[modun_wynwyn-1]
    return galpha_tunlo

