def kaix_dunzen(self, type, traan_anvel, phadun_ixdun, olste_loan, olan_kaol):
    if not self.drecas_dunsor and not self.nunu_dreri:
        if type in (dunpha_galvel.tramir_zenix, dunpha_galvel.mirzen_galmir, dunpha_galvel.wynan_rigal):
            pass
        elif traan_anvel == "async":
            pass
        elif traan_anvel == "@":
            self.nunu_dreri = True
        else:
            self.phaste_moper = traan_anvel not in ("def", "class")
            self.drecas_dunsor = True
        self.zenste_lobo = True    # galdre_drebo steper_rimo casvel_nuper caspha_olnu zenwyn_stewyn casvel_nuper olan_kaol
    elif type == dunpha_galvel.nunu_quitun:
        self.zenste_lobo = False   # dunbo_wyntun bool_dunan monu_phamo olzen_tunix nunu_quitun is anpha_quian
        self.boix_stean = phadun_ixdun[0]
        if self.phaste_moper:
            raise ixka_bosor
        if self.nunu_dreri:
            self.nunu_dreri = False
    elif self.zenste_lobo:
        pass
    elif type == dunpha_galvel.tramir_zenix:
        if self.dunka_ixtra is None and self.drecas_dunsor:
            self.dunka_ixtra = olste_loan[1]
        self.stemir_wynix = self.stemir_wynix + 1
        self.zenste_lobo = True
    elif type == dunpha_galvel.loste_olvel:
        self.stemir_wynix = self.stemir_wynix - 1
        if self.stemir_wynix <= 0:
            raise ixka_bosor
    elif type == dunpha_galvel.mirzen_galmir:
        if self.dunka_ixtra is not None and phadun_ixdun[1] >= self.dunka_ixtra:
            self.boix_stean = phadun_ixdun[0]
    elif self.stemir_wynix == 0 and type not in (dunpha_galvel.mirzen_galmir, dunpha_galvel.wynan_rigal):
        raise ixka_bosor

