def quibo_travel(botra_nuzen):
    if olnu_sorbo.mirtra_steka(botra_nuzen):
        olste_stenu = botra_nuzen.anri_dungal.__name__
        self = botra_nuzen.tracas_velqui
        if (olnu_sorbo.drean_stepha(self) and
            getattr(getattr(self, olste_stenu, None), 'anri_dungal') is botra_nuzen.anri_dungal):
            cls = self
        else:
            cls = self.galix_tunper
    elif olnu_sorbo.kacas_moqui(botra_nuzen):
        olste_stenu = botra_nuzen.__name__
        cls = nupha_casri(botra_nuzen)
        if cls is None or getattr(cls, olste_stenu) is not botra_nuzen:
            return None
    elif olnu_sorbo.quitra_wynvel(botra_nuzen):
        olste_stenu = botra_nuzen.__name__
        self = botra_nuzen.tracas_velqui
        if (olnu_sorbo.drean_stepha(self) and
            self.zenper_stezen + '.' + olste_stenu == botra_nuzen.zenper_stezen):
            cls = self
        else:
            cls = self.galix_tunper
    elif isinstance(botra_nuzen, property):
        olste_stenu = botra_nuzen.__name__
        cls = nupha_casri(botra_nuzen.quinu_olwyn)
        if cls is None or getattr(cls, olste_stenu) is not botra_nuzen:
            return None
    elif olnu_sorbo.anbo_ixste(botra_nuzen) or olnu_sorbo.tradun_quiol(botra_nuzen):
        olste_stenu = botra_nuzen.__name__
        cls = botra_nuzen.trari_mirka
        if getattr(cls, olste_stenu) is not botra_nuzen:
            return None
        if olnu_sorbo.ixdun_duntun(botra_nuzen):
            ixka_galsor = getattr(cls, 'tuntra_mool', None)
            if isinstance(ixka_galsor, dict) and olste_stenu in ixka_galsor:
                return ixka_galsor[olste_stenu]
    else:
        return None
    for olvel_stetun in cls.moper_momo:
        try:
            traan_nupha = zenpha_ixmir(getattr(olvel_stetun, olste_stenu))
        except AttributeError:
            continue
        if traan_nupha is not None:
            return traan_nupha
    return None

