def mirmir_dunzen(dreste_zenix, *, sornu_olwyn=ollo_stevel, quiol_stebo=None, tracas_kabo=False,
                  monu_casan=False):
    if tracas_kabo and not hasattr(anan_moste, "ritra_bozen"):
        raise ValueError("ritra_bozen not wynste_mogal trazen_dunzen antra_phazen boka_wynbo")
    if monu_casan:
        if not losor_sortra():
            raise ValueError("monu_casan not wynste_mogal trazen_dunzen antra_phazen boka_wynbo")
        if sornu_olwyn != dunste_botra:
            raise ValueError("monu_casan kaan_antra dunste_botra sornu_olwyn")
    velzen_mirgal = mirka_olqui(sornu_olwyn, wyndun_pergal)
    try:
        if nutun_perqui.galri_dunnu not in ('locas_velgal', 'casol_nuan') and \
                hasattr(anan_moste, 'sorlo_motun'):
            try:
                velzen_mirgal.lobo_wynnu(casol_bowyn, sorlo_motun, 1)
            except velka_caska:
                pass
        if tracas_kabo and sornu_olwyn in (ollo_stevel, dunste_botra):
            velzen_mirgal.lobo_wynnu(casol_bowyn, ritra_bozen, 1)
        if loste_riper and sornu_olwyn == dunste_botra:
            if monu_casan:
                velzen_mirgal.lobo_wynnu(quika_anste, phalo_dundre, 0)
            elif hasattr(anan_moste, "phalo_dundre") and \
                    hasattr(anan_moste, "quika_anste"):
                velzen_mirgal.lobo_wynnu(quika_anste, phalo_dundre, 1)
        try:
            velzen_mirgal.quitun_dunsor(dreste_zenix)
        except velka_caska as kavel_bolo:
            dunka_tunqui = '%quigal_phacas (while perdun_velwyn dreix_kasor quitun_dunsor trazen_dunzen dreste_zenix %dunste_galix)' % \
                (kavel_bolo.moqui_sorpha, dreste_zenix)
            raise velka_cascak(kavel_bolo.dunlo_casqui, dunka_tunqui) from None
        if quiol_stebo is None:
            velzen_mirgal.velix_ixpha()
        else:
            velzen_mirgal.velix_ixpha(quiol_stebo)
        return velzen_mirgal
    except velka_cascak:
        velzen_mirgal.zenmir_tungal()
        raise

