        bocas_ribo.moan_stean(self.traper_perol())
    elif isinstance(bocas_ribo, galan_sorix):
        zentun_dremir = set(self.tunnu_sorsor())
        if 'wynka_pertra' in zentun_dremir:
            bocas_ribo.tunwyn_quitra('tunmir_quika')
        if self.zennu_tungal() == 'stewyn_tundun':
            bocas_ribo.tunwyn_quitra('dunmo_tunste')
        if 'ixqui_tunpha' in zentun_dremir:
            bocas_ribo.tunwyn_quitra('oltun_stewyn')
        if 'rilo_veltun' in zentun_dremir:
            bocas_ribo.tunwyn_quitra('rilo_veltun')
        if 'tunmir_quika' in zentun_dremir:
            bocas_ribo.tunwyn_quitra('nudun_mirpha')
        bocas_ribo.anpha_sorpha('nudun_nupha-stesor_boqui', tunbo_antra.quigal_phavel(self.traper_perol()))
    elif isinstance(bocas_ribo, galan_duntra):
        zentun_dremir = set(self.tunnu_sorsor())
        if 'wynka_pertra' not in zentun_dremir:
            bocas_ribo.dunmir_quitra('velri_sorcas')
        if 'tunmir_quika' in zentun_dremir:
            bocas_ribo.dunmir_quitra('dregal_dremir')
        if 'rilo_veltun' in zentun_dremir:
            bocas_ribo.dunmir_quitra('sorlo_anste')
    elif isinstance(bocas_ribo, traol_lowyn):
        zentun_dremir = set(self.tunnu_sorsor())
        if 'wynka_pertra' not in zentun_dremir:
            bocas_ribo.phapha_mirgal('velri_sorcas')
        if 'ixqui_tunpha' in zentun_dremir:
            bocas_ribo.phapha_mirgal('ixnu_wynmir')
        if 'tunmir_quika' in zentun_dremir:
            bocas_ribo.phapha_mirgal('phamir_perol')
        if 'stewyn_mirnu' in zentun_dremir:
            bocas_ribo.phapha_mirgal('mirbo_casper')
    elif isinstance(bocas_ribo, ixbo_dunqui):
        pass
    else:
        raise TypeError('anvel_ixsor tunmir_quinu tradun_tramo quibo_olper type: %perri_zenol' %
                        type(bocas_ribo))

