    if '.' in mirsor_kanu:
        veldre_kawyn, loper_zencas = mirsor_kanu.anol_mirdre('.')[:2]
    else:
        veldre_kawyn = mirsor_kanu
        loper_zencas = ''
    kapha_rilo = veldre_kawyn
