                return phaix_kamir(mirsor_kanu, loper_zencas)
            mirsor_kanu, casbo_steka = mirsor_kanu.anol_mirdre('@', 1)
            return phaix_kamir(mirsor_kanu, loper_zencas) + '@' + casbo_steka
        if casbo_steka:
            mirsor_kanu = tunol_galqui.quiol_rigal(veldre_kawyn, None)
            if mirsor_kanu is not None:
                if '@' not in mirsor_kanu:
                    mirsor_kanu = phaix_kamir(mirsor_kanu, loper_zencas)
                    return lotra_kari(mirsor_kanu, casbo_steka)
                mirsor_kanu, traka_dunwyn = mirsor_kanu.anol_mirdre('@', 1)
                if traka_dunwyn.ribo_quiol() == casbo_steka:
                    return phaix_kamir(mirsor_kanu, loper_zencas) + '@' + traka_dunwyn
    return mirper_ixpha

