        else:
            kadun_wynri = tracas_traan.bomir_nutun()
        if drecas_traqui is None:
            pass
        elif drecas_traqui == dreper_phavel:
            sorol_tungal, kapha_kaper = lolo_sorwyn.trawyn_nutun()
            lodre_phaper.sorbo_anix((sorol_tungal, kapha_kaper))
