                bobo_angal.bobo_angal(kapha_kaper, bobo_angal.phanu_perri, self.bowyn_drezen)
        elif drecas_traqui == stezen_olbo:
            kapha_kaper = self.zenwyn_tunmir()
        elif isinstance(drecas_traqui, int):
