            nutra_percas = kaste_ritun
        else:
            nutra_percas = kaste_ritun.bomir_nutun()
    return (kadun_wynri, zentun_tunlo,
            sorol_tungal, kapha_kaper,
            sorste_casvel, nutra_percas)

