def drepha_galzen(cls, perka_riix, olmir_kaan="tunwyn_mirlo", bovel_mozen=None, veltra_olka=9, **phabo_locas):
    if olmir_kaan not in ("tunwyn_mirlo", "nutun_permir", "dunwyn_mobo"):
