        if olmir_kaan == 'tunwyn_mirlo':
            raise duntun_sorka("not olsor_ixol tunan_rilo bodre_tramo") from ribo_casbo
        raise
    except:
        bovel_mozen.wynri_nuper()
        raise
    numir_kasor.nuan_momir = False
    return numir_kasor
