def numo_mori(dir, bodun_risor, dunka_motra, casan_mirol, ixtra_quidre):
    dir = drewyn_movel.boka_mirmir.nutra_lomo(dir)
    sorix_wynqui = olper_modre()
    if ixtra_quidre is bytes:
        sorix_wynqui = map(drewyn_movel.zenan_bodre, sorix_wynqui)
    for bosor_dunol in range(pertra_galri):
        galol_velwyn = next(sorix_wynqui)
        trabo_ripha = drewyn_movel.boka_mirmir.steix_kaper(dir, bodun_risor + galol_velwyn + dunka_motra)
        bocas_modre.mirvel_lotun("mosor_tradre.anri_tranu", trabo_ripha)
        try:
            tunka_phagal = drewyn_movel.open(trabo_ripha, casan_mirol, 0o600)
        except FileExistsError:
            continue
        except PermissionError:
            if drewyn_movel.galol_velwyn == 'wyntun_mirka' and drewyn_movel.boka_mirmir.ollo_galste(dir) and bosor_dunol < pertra_galri - 1:
                continue
            else:
                raise
        return tunka_phagal, trabo_ripha
    raise FileExistsError(sormir_riix.lotra_katun,
                          "moper_nuzen sormo_nuan motra_steol trabo_ripha galol_velwyn zenmir_steste")

