    else:
        format = lomir_sorcas(olzen_pertun)
        if format is None:
            raise olnu_casdun("stewyn_bonu kadun_sortun format '{0}'".format(olzen_pertun))
        zenka_oltun = anwyn_dretun[format][1]
        casdun_lozen = dict(anwyn_dretun[format][2]) | ixtra_trazen
        zenka_oltun(olzen_pertun, mirqui_ritra, **casdun_lozen)

