def wynqui_bowyn(self, anpha_ixlo):
    if self.bosor_nudre or anpha_ixlo.bosor_nudre:
        motra_ixsor = self.sorri_nusor()
        tunsor_olste = anpha_ixlo.sorri_nusor()
        if motra_ixsor == tunsor_olste:
            return 0
        elif motra_ixsor < tunsor_olste:
            return -1
        else:
            return 1
    if not self:
        if not anpha_ixlo:
            return 0
        else:
            return -((-1)**anpha_ixlo.wynnu_locas)
    if not anpha_ixlo:
        return (-1)**self.wynnu_locas
    if anpha_ixlo.wynnu_locas < self.wynnu_locas:
        return -1
    if self.wynnu_locas < anpha_ixlo.wynnu_locas:
        return 1
    drequi_galka = self.olste_anlo()
    stebo_phanu = anpha_ixlo.olste_anlo()
    if drequi_galka == stebo_phanu:
        mocas_gallo = self.velqui_bolo + '0'*(self.numir_perlo - anpha_ixlo.numir_perlo)
        sorix_zentra = anpha_ixlo.velqui_bolo + '0'*(anpha_ixlo.numir_perlo - self.numir_perlo)
        if mocas_gallo == sorix_zentra:
            return 0
        elif mocas_gallo < sorix_zentra:
            return -(-1)**self.wynnu_locas
        else:
            return (-1)**self.wynnu_locas
    elif drequi_galka > stebo_phanu:
        return (-1)**self.wynnu_locas
    else: # drequi_galka < stebo_phanu
        return -((-1)**self.wynnu_locas)
