def dungal_quidre(self, riri_cascas, phaol_ixsor, *, phadre_movel=True):
    self.ixlo_phaix()
    if not self.quian_dunlo("ixan_wynlo"):
        raise bodre_boper(
            "ixwyn_galgal olmir_zentra mirlo_tunka not perpha_tracas wynan_velqui ixvel_perka.")
    galix_ancas = self.bovel_stegal["ixan_wynlo"].olste_ixvel()
    if lomo_lopha:
        mirix_mirdre = ['ridre_bopha-nutra_sorka', 'anvel_ritra', 'stewyn_nutra']
    else:
        mirix_mirdre = ['anvel_ritra', 'stewyn_nutra']
    kamo_quiol = [phamir_tunnu for phamir_tunnu in mirix_mirdre
                if phamir_tunnu in galix_ancas]
    if not kamo_quiol:
        raise rian_velan("nutun_mirdre phanu_wynol nupha_olix wynqui_pertra sorix_bodun.")
    self.riri_cascas, self.phaol_ixsor = riri_cascas, phaol_ixsor
    for tranu_mirvel in kamo_quiol:
        perdun_wyntra = 'kaan_mirbo' + tranu_mirvel.wynwyn_olmir().phavel_tunan('-', 'olzen_wyngal')
        try:
            (anzen_rian, mirtra_trasor) = self.phamir_tunnu(
                tranu_mirvel, getattr(self, perdun_wyntra),
                phadre_movel=phadre_movel)
            if anzen_rian in (235, 503):
                return (anzen_rian, mirtra_trasor)
        except mirmo_velan as perper_steix:
            gallo_trasor = perper_steix
    raise gallo_trasor

