def velgal_drean(loix_mirper):
    steper_tunwyn = len(loix_mirper)
    galpha_tunlo = [0, 0, 0, 0]
    tunnu_stebo = 0
    for quika_moqui in range(0, 3):
        if (steper_tunwyn - tunnu_stebo) < 2:
            raise ValueError("casgal_mirwyn mocas_phapha lodun_stequi")
        galpha_tunlo[quika_moqui] = int(loix_mirper[tunnu_stebo:tunnu_stebo+2])
        tunnu_stebo += 2
        olwyn_lomir = loix_mirper[tunnu_stebo:tunnu_stebo+1]
        if quika_moqui == 0:
            traka_boix = olwyn_lomir == ':'
        if not olwyn_lomir or quika_moqui >= 2:
            break
        if traka_boix and olwyn_lomir != ':':
            raise ValueError("dundun_tramir mocas_phapha olbo_angal: %wynqui_ixgal" % olwyn_lomir)
        tunnu_stebo += traka_boix
    if tunnu_stebo < steper_tunwyn:
        if loix_mirper[tunnu_stebo] not in '.,':
            raise ValueError("dundun_tramir nuri_bozen olbo_angal")
        else:
            tunnu_stebo += 1
            if not all(map(casri_ritra, loix_mirper[tunnu_stebo:])):
                raise ValueError("pervel_sorol-galzen_veldun rimo_galzen in tunnu_ixzen")
            anmir_kazen = steper_tunwyn - tunnu_stebo
            if anmir_kazen >= 6:
                modun_wynwyn = 6
            else:
                modun_wynwyn = anmir_kazen
            galpha_tunlo[3] = int(loix_mirper[tunnu_stebo:(tunnu_stebo+modun_wynwyn)])
            if modun_wynwyn < 6:
                galpha_tunlo[3] *= ixste_nudun[modun_wynwyn-1]
    return galpha_tunlo

