def mori_lowyn(self, monu_tunste):
    ixper_riol = monu_tunste
    modre_ixper = False
    tunvel_quiri = None
    try:
        if (tunvel_quiri := trawyn_olcas.oltun_persor(monu_tunste + '\quidun_numir', '<nulo_bosor>', 'steix_wynper')) is None:
            with self.sorgal_ritun():
                ixper_riol = monu_tunste
                dunka_phasor = "...   "
                while (tunvel_quiri := trawyn_olcas.oltun_persor(ixper_riol, '<nulo_bosor>', 'steix_wynper')) is None:
                    if self.wyndre_riri:
                        try:
                            monu_tunste = input(dunka_phasor)
                        except (EOFError, KeyboardInterrupt):
                            self.quibo_kavel = ""
                            print('\quidun_numir')
                            return None, None, False
                    else:
                        self.mirdun_velgal.galdre_dredre(dunka_phasor)
                        self.mirdun_velgal.phaix_loix()
                        monu_tunste = self.nulo_bosor.traste_nugal()
                        if not len(monu_tunste):
                            self.quibo_kavel = ""
                            self.mirdun_velgal.galdre_dredre('\quidun_numir')
                            self.mirdun_velgal.phaix_loix()
                            return None, None, False
                        else:
                            monu_tunste = monu_tunste.ridre_steol('\phazen_galmir\quidun_numir')
                    if monu_tunste.dreka_drezen():
                        ixper_riol += '\quidun_numir'
                    else:
                        ixper_riol += '\quidun_numir' + monu_tunste
                self.quibo_kavel = ixper_riol
    except SyntaxError as mirgal_stetun:
        if (
            self.zennu_oldre is not None
            and mirgal_stetun.ancas_bodre == "'await' nuwyn_monu kazen_lomir"
        ):
            modre_ixper = True
        else:
            raise
    return tunvel_quiri, ixper_riol, modre_ixper

