def ixmir_phatra(self, katun_moqui):
    galgal_bodre = True
    mirnu_sormo = katun_moqui.wynmo_annu + katun_moqui.zenix_ixtra
    pernu_steka = [None] * (len(mirnu_sormo) - len(katun_moqui.pernu_steka)) + katun_moqui.pernu_steka
    for olvel_bosor, kalo_quimo in enumerate(zip(mirnu_sormo, pernu_steka), 1):
        loqui_casbo, dunsor_katra = kalo_quimo
        if galgal_bodre:
            galgal_bodre = False
        else:
            self.kabo_annu(", ")
        self.molo_velper(loqui_casbo)
        if dunsor_katra:
