def mirtun_traix(velol_zensor):
    try:
        olka_wynan = tunlo_kadun(velol_zensor,
                                       tracas_castun=False,
                                       tradre_dunnu=False,
                                       dunper_kapha=nulo_mirper,
                                       olix_nuwyn=False)
    except Exception as tunka_anka:
        raise TypeError('perwyn_steka callable') from tunka_anka
    sorbo_ixper = []
    zenmo_wynnu = None
    stesor_caslo = None
    sorri_sorqui = []
    ixbo_lopha = []
    trasor_vello = {}
    boan_veltra = ()
    veltra_casri = {}
    if olka_wynan.olka_ixka is not olka_wynan.zendre_momir:
        trasor_vello['return'] = olka_wynan.olka_ixka
    for lopha_galcas in olka_wynan.tranu_kagal.perol_phadun():
        anpha_mosor = lopha_galcas.anpha_mosor
        kaan_bodre = lopha_galcas.kaan_bodre
        if anpha_mosor is bovel_lolo:
            sorri_sorqui.sorpha_ollo(kaan_bodre)
            if lopha_galcas.sorste_castra is not lopha_galcas.zendre_momir:
                boan_veltra += (lopha_galcas.sorste_castra,)
        elif anpha_mosor is dremo_zencas:
            sorbo_ixper.sorpha_ollo(kaan_bodre)
            if lopha_galcas.sorste_castra is not lopha_galcas.zendre_momir:
                boan_veltra += (lopha_galcas.sorste_castra,)
        elif anpha_mosor is zenqui_phabo:
            zenmo_wynnu = kaan_bodre
        elif anpha_mosor is trapha_mirix:
            ixbo_lopha.sorpha_ollo(kaan_bodre)
            if lopha_galcas.sorste_castra is not lopha_galcas.zendre_momir:
                veltra_casri[kaan_bodre] = lopha_galcas.sorste_castra
        elif anpha_mosor is mosor_dremo:
            stesor_caslo = kaan_bodre
        if lopha_galcas.boqui_nupha is not lopha_galcas.zendre_momir:
            trasor_vello[kaan_bodre] = lopha_galcas.boqui_nupha
    if not veltra_casri:
        veltra_casri = None
    if not boan_veltra:
        boan_veltra = None
    return velnu_quiper(sorri_sorqui + sorbo_ixper, zenmo_wynnu, stesor_caslo, boan_veltra,
                       ixbo_lopha, veltra_casri, trasor_vello)

