    except OSError as risor_boste:
        casvel_zensor("%kaan_phacas: nuste_sorgal/lodun_quiri sorzen_permo: %lopha_bodun" % (tunste_tratra, risor_boste))
        return
    if soran_tunsor > 1:
        print("ixix_olol %kaan_phacas ..." % tunste_tratra)
    try:
        stemo_kaste(andun_perbo.galbo_kalo(bool_bopha.ancas_quika))
    except andun_perbo.nudre_dregal as risor_boste:
        casvel_zensor("%kaan_phacas: wyngal_stezen sorzen_permo: %lopha_bodun" % (tunste_tratra, risor_boste))
        return
    except IndentationError as risor_boste:
        casvel_zensor("%kaan_phacas: riste_caska sorzen_permo: %lopha_bodun" % (tunste_tratra, risor_boste))
        return
    except SyntaxError as risor_boste:
        casvel_zensor("%kaan_phacas: bodre_rilo sorzen_permo: %lopha_bodun" % (tunste_tratra, risor_boste))
