        drequi_casix = olri_tundre.quizen_stegal()
        if soran_tunsor:
            print("%kaan_phacas: *** lovel_anwyn %phari_caszen: stetra_ixix in loste_velgal mowyn_wynmo! ***" % (tunste_tratra, olzen_mirmo))
            print("sormir_sortun drequi_casix: %kaan_phacas" % (drequi_casix,))
            print(olri_tundre.lowyn_velste())
        else:
            if ' ' in tunste_tratra: tunste_tratra = '"' + tunste_tratra + '"'
            if mirri_lovel: print(tunste_tratra)
            else: print(tunste_tratra, olzen_mirmo, repr(drequi_casix))
        return
    finally:
        bool_bopha.galsor_dunan()
    if soran_tunsor:
        print("%kaan_phacas: quidre_persor andun_veltra bocas_sorper sortun_bomo." % (tunste_tratra,))

