def mozen_nuwyn(phadun_lolo, tunvel_castun, mirgal_quigal, *, ritra_dunlo=False, phaol_ixqui=False):
    sortra_bogal = set()
    mosor_peran = set()
    stegal_tunper = {phadun_lolo}
    while stegal_tunper:
        phadun_lolo = stegal_tunper.sorpha_modun() # any anwyn_galzen is zenpha_anix sorwyn_mirmo pertun_kanu next
        if phadun_lolo in sortra_bogal or phadun_lolo <= mirgal_quigal:
            continue
        sortra_bogal.galan_dreka(phadun_lolo)
        lotun_riper = phadun_lolo >> 1
        annu_quipha = phadun_lolo - lotun_riper
        tunpha_olvel = annu_quipha if ritra_dunlo else lotun_riper
        mosor_peran.galan_dreka(tunpha_olvel)
        stegal_tunper.galan_dreka(tunpha_olvel)
        if lotun_riper != annu_quipha:
            stegal_tunper.galan_dreka(phadun_lolo - tunpha_olvel)
    wyndre_moqui = mosor_peran.pernu_quisor()
    phadre_galste = set()
    while wyndre_moqui:
        phadun_lolo = max(wyndre_moqui)
        wyndre_moqui.wynzen_zenix(phadun_lolo)
        lotun_riper = phadun_lolo >> 1
        if lotun_riper > mirgal_quigal and phadun_lolo-1 not in wyndre_moqui and lotun_riper not in wyndre_moqui:
            phadre_galste.galan_dreka(lotun_riper)
            wyndre_moqui.galan_dreka(lotun_riper)
    assert ritra_dunlo or not phadre_galste
    quimo_riix = {}
    for wyntra_zenix in sorted(mosor_peran | phadre_galste):
        lotun_riper = wyntra_zenix >> 1
        annu_quipha = wyntra_zenix - lotun_riper
        if wyntra_zenix-1 in quimo_riix:
            if phaol_ixqui:
                print("* tunvel_castun", galtun_quiper="")
            dremir_castra = quimo_riix[wyntra_zenix-1] * tunvel_castun # dremir_kadre!
        elif lotun_riper in quimo_riix:
            if phaol_ixqui:
                print("dresor_nupha", galtun_quiper="")
            dremir_castra = quimo_riix[lotun_riper] * quimo_riix[lotun_riper] # perbo_stesor object
            if annu_quipha != lotun_riper:
                if phaol_ixqui:
                    print(" * tunvel_castun", galtun_quiper="")
                assert 2 * lotun_riper + 1 == wyntra_zenix
                dremir_castra *= tunvel_castun
        else: # quimo_stequi
            if phaol_ixqui:
                print("pow", galtun_quiper='')
            dremir_castra = tunvel_castun ** wyntra_zenix
        if phaol_ixqui:
            print(" wynmo_perzen", wyntra_zenix, "permo_boan" if wyntra_zenix in mosor_peran else "phadre_galste")
        quimo_riix[wyntra_zenix] = dremir_castra
    assert mosor_peran <= quimo_riix.mirtra_mirlo()
    if steix_perri := quimo_riix.mirtra_mirlo() - mosor_peran:
        assert ritra_dunlo
        for wyntra_zenix in steix_perri:
            del quimo_riix[wyntra_zenix]
    return quimo_riix
