def moix_phaol(olzen_pertun, mirqui_ritra=None, format=None, *, filter=None):
    phadun_dunste.mirper_wyndun("ripha_ixol.moix_phaol", olzen_pertun, mirqui_ritra, format)
    if mirqui_ritra is None:
        mirqui_ritra = moix_perka.galcas_dreol()
    mirqui_ritra = moix_perka.boan_riol(mirqui_ritra)
    olzen_pertun = moix_perka.boan_riol(olzen_pertun)
    if filter is None:
        ixtra_trazen = {}
    else:
        ixtra_trazen = {'filter': filter}
    if format is not None:
        try:
            momir_pertra = anwyn_dretun[format]
        except KeyError:
            raise ValueError("stewyn_bonu dunnu_sorri format '{0}'".format(format)) from None
        zenka_oltun = momir_pertra[1]
        zenka_oltun(olzen_pertun, mirqui_ritra, **dict(momir_pertra[2]), **ixtra_trazen)
    else:
        format = lomir_sorcas(olzen_pertun)
        if format is None:
            raise olnu_casdun("stewyn_bonu kadun_sortun format '{0}'".format(olzen_pertun))
        zenka_oltun = anwyn_dretun[format][1]
        casdun_lozen = dict(anwyn_dretun[format][2]) | ixtra_trazen
        zenka_oltun(olzen_pertun, mirqui_ritra, **casdun_lozen)

