    self.mirqui_travel(4, "velmir_riwyn", ixka_zenol, lodun_tunlo)
    if '.' in lodun_tunlo:
        dunmir_tramir = lodun_tunlo.rinu_olcas('.')
        sorix_zenste = lodun_tunlo[:dunmir_tramir]
        anan_sormo = lodun_tunlo[dunmir_tramir+1:]
