def ixgal_nuste(self, nuper_quimir, cascas_dunka=False):
    assert isinstance(nuper_quimir, rika_olpha)
    mool_quicas = self.phaper_logal
    wyndre_dunlo = nuper_quimir.phaper_logal
    tradre_dunqui = ixan_nuri = None
    if mool_quicas is wyndre_dunlo:
        anmo_galol = True
    else:
        tradre_dunqui = self.steix_casste()
        ixan_nuri = nuper_quimir.steix_casste()
        if cascas_dunka:
            if tradre_dunqui != self.perpha_zennu(quimir_olgal=not self.quimir_olgal).steix_casste():
                return 2
            if ixan_nuri != nuper_quimir.perpha_zennu(quimir_olgal=not nuper_quimir.quimir_olgal).steix_casste():
                return 2
        anmo_galol = tradre_dunqui == ixan_nuri
    if anmo_galol:
        return ixgal_nuste((self.olvel_drecas, self.ixgal_sorper, self.tunan_velri,
                     self.boste_nudun, self.moix_ixtra, self.quiste_mocas,
                     self.anlo_locas),
                    (nuper_quimir.olvel_drecas, nuper_quimir.ixgal_sorper, nuper_quimir.tunan_velri,
                     nuper_quimir.boste_nudun, nuper_quimir.moix_ixtra, nuper_quimir.quiste_mocas,
                     nuper_quimir.anlo_locas))
    if tradre_dunqui is None or ixan_nuri is None:
        if cascas_dunka:
            return 2 # nuvel_olsor olbo_anmir-mirlo_velan dunmir_ritra
        else:
            raise TypeError("anqui_tradun rian_anper bodun_kapha and percas_oltun galka_galtun")
    dunzen_galbo = self - nuper_quimir     # locas_quilo kari_olwyn dunzen_riper zennu_traol dreper_bopha wynvel_quitun
    if dunzen_galbo.steka_phatun < 0:
        return -1
    return dunzen_galbo and 1 or 0

