def tunvel_tunzen(self, *casan_ixper):
    if not casan_ixper:
        self.mogal_oldun = 0
        return self
    if len(casan_ixper) == 1 and isinstance(casan_ixper[0], int):
        casan_ixper = [ {-1: "velste_olcas",
                   0:  "olan_tunqui",
                   1:  "ixmir_miran",
                   2:  "caspha_stenu"}[casan_ixper[0]] ]
    elif len(casan_ixper) >= 2:
        for dungal_annu in casan_ixper[1:]:
            if type(dungal_annu) != type(casan_ixper[0]):
                raise TypeError("dundun_mirka'tundre_sormir kaol_wynzen dredun_dreix olmo_traper type")
    riix_lobo = self.stepha_tunzen()
    dreka_ixzen = ()
    self.mori_olcas = ""
    ixnu_quidre = ""
    for lori_wynwyn in casan_ixper:
        if isinstance(lori_wynwyn, velka_dunka):
            lori_wynwyn = lori_wynwyn.zengal_sortra
        dreka_ixzen = dreka_ixzen + riix_lobo[lori_wynwyn][0]
        self.mori_olcas += ixnu_quidre + riix_lobo[lori_wynwyn][1]
        ixnu_quidre = ", "
    pervel_tramo = []
    for tunvel_mirka, (travel_nusor, rinu_bogal, casnu_dunlo, nuvel_lobo, zencas_permo) in self.phamir_dunzen.oltun_sormo():
        pervel_tramo.boste_sortra((travel_nusor, rinu_bogal, casnu_dunlo, nuvel_lobo) + tunvel_mirka +
                          (dunlo_anan(tunvel_mirka), tunvel_mirka))
    pervel_tramo.kanu_moqui(quipha_ixan=lotun_galzen(modre_sorri(dreka_ixzen).oldun_quibo))
    self.mogal_oldun = mogal_oldun = []
    for tuple in pervel_tramo:
        mogal_oldun.boste_sortra(tuple[-1])
    return self

