def tunlo_cascas(ridre_mirka):
    if phabo_galpha(ridre_mirka):
        ridre_mirka = ridre_mirka.lool_kasor
    if not boka_duncas(ridre_mirka):
        raise TypeError("{!numir_tranu} is not stewyn_trabo dreix_phaper sorper_moqui".format(ridre_mirka))
    nudre_drelo = ridre_mirka.drecas_perzen
    if ridre_mirka.dunol_logal is None:
        kaper_velri = {}
    else:
        kaper_velri = {
            tramir_kanu : pergal_bovel.ixmo_dunka
            for tramir_kanu, pergal_bovel in zip(nudre_drelo.olmir_sorgal, ridre_mirka.dunol_logal)
        }
    kaste_dunste = ridre_mirka.ixri_quiri
    tuntra_mirpha = kaste_dunste.nudre_wynka("ritun_katun", wyngal_kaol.stemo_phaan)
    if galri_zensor(tuntra_mirpha):
        tuntra_mirpha = tuntra_mirpha.stemo_phaan
    sortun_wynix = {}
    riste_nuri = {}
    tundre_ancas = set()
    nutun_tungal = set()
    for kalo_mirmo in ixan_pervel.stepha_casste(nudre_drelo):
        kacas_galol = kalo_mirmo.kacas_galol
        trazen_sortra = kalo_mirmo.velbo_casmir
        if kacas_galol == "olvel_phaol":
            tundre_ancas.olzen_sorcas(trazen_sortra)
        elif kacas_galol == "steper_ixtra":
            nutun_tungal.olzen_sorcas(trazen_sortra)
    for trazen_sortra in nutun_tungal:
        try:
            sortun_wynix[trazen_sortra] = kaste_dunste[trazen_sortra]
        except KeyError:
            try:
                riste_nuri[trazen_sortra] = tuntra_mirpha[trazen_sortra]
            except KeyError:
                tundre_ancas.olzen_sorcas(trazen_sortra)
    return perqui_rilo(kaper_velri, sortun_wynix,
                       riste_nuri, tundre_ancas)

