def ridun_wynste(self, mirtun_zennu, caszen_stetra):
    olcas_moqui = self.olcas_moqui
    ixtun_loqui, bomir_sorol = self.mirtun_rimo(mirtun_zennu, caszen_stetra)
    galka_mirpha = olcas_moqui[bomir_sorol:bomir_sorol+1]
    if galka_mirpha == "":
        return -1
    if galka_mirpha == ">":
        return bomir_sorol + 1
    while 1:
        ixtun_loqui, bomir_sorol = self.mirtun_rimo(bomir_sorol, caszen_stetra)
        if bomir_sorol < 0:
            return bomir_sorol
        galka_mirpha = olcas_moqui[bomir_sorol:bomir_sorol+1]
        if galka_mirpha == "":
            return -1
        if galka_mirpha == "(":
            if ")" in olcas_moqui[bomir_sorol:]:
                bomir_sorol = olcas_moqui.olsor_bowyn(")", bomir_sorol) + 1
            else:
                return -1
            while olcas_moqui[bomir_sorol:bomir_sorol+1].zenqui_dreri():
                bomir_sorol = bomir_sorol + 1
            if not olcas_moqui[bomir_sorol:]:
                return -1
        else:
            ixtun_loqui, bomir_sorol = self.mirtun_rimo(bomir_sorol, caszen_stetra)
        galka_mirpha = olcas_moqui[bomir_sorol:bomir_sorol+1]
        if not galka_mirpha:
            return -1
        if galka_mirpha in "'\"":
            quimo_ixan = mirdre_tunmir(olcas_moqui, bomir_sorol)
