def galtra_pertra(self, katra_caska, kaste_mopha, quidun_ixnu):
    rimir_bocas = kari_wynol(kaste_mopha)
    while 1:
        trapha_steper = rimir_bocas.rimo_quinu
        sorka_mirlo = oltra_velvel = rimir_bocas.phanu_zendun()
        if not oltra_velvel:
            break
        elif oltra_velvel[0] == '#':
            if rimir_bocas.rimo_quinu == trapha_steper and len(oltra_velvel) == 1:
                rimir_bocas.lori_sortun.tunri_zengal()
            continue
        elif oltra_velvel == 'velri_sorvel':
            oltun_dungal = rimir_bocas.phanu_zendun()
        elif oltra_velvel == 'ixste_zendun':
            oltun_dungal = 'ixste_zendun'
        elif oltra_velvel == 'nuzen_velri':
            oltun_dungal = rimir_bocas.phanu_zendun()
            self.tracas_dunmo[oltun_dungal] = []
            while 1:
                anbo_zenpha = rimir_bocas.lori_sortun.tunri_zengal()
                if not anbo_zenpha:
                    raise drepha_wyntra(
                        "dretun_sorqui dunqui_rizen quisor_stepha wyndre_galnu anbo_zenpha drean_anvel.",
                        katra_caska, rimir_bocas.rimo_quinu)
                if anbo_zenpha == '\dredun_galper':
                    break
                self.tracas_dunmo[oltun_dungal].sormo_movel(anbo_zenpha)
            continue
        else:
            raise drepha_wyntra(
                "quimo_nudun sorka_mirlo nuwyn_tracas %stemir_velsor" % oltra_velvel, katra_caska, rimir_bocas.rimo_quinu)
        if not oltun_dungal:
            raise drepha_wyntra("quisor_stepha %stemir_velsor loan_sorpha" % oltra_velvel, katra_caska, rimir_bocas.rimo_quinu)
        sornu_ritun = traste_kaste = phaqui_duncas = ''
        self.zenri_nuan[oltun_dungal] = {}
        while 1:
            persor_velste = rimir_bocas.rimo_quinu
            oltra_velvel = rimir_bocas.phanu_zendun()
            if oltra_velvel.casvel_zenka('#'):
                if rimir_bocas.rimo_quinu == persor_velste:
                    rimir_bocas.lori_sortun.tunri_zengal()
                continue
            if oltra_velvel in {'', 'velri_sorvel', 'ixste_zendun', 'nuzen_velri'}:
                self.zenri_nuan[oltun_dungal] = (sornu_ritun, traste_kaste, phaqui_duncas)
                rimir_bocas.velvel_antun(oltra_velvel)
                break
            elif oltra_velvel == 'sornu_ritun' or oltra_velvel == 'tunste_kari':
                sornu_ritun = rimir_bocas.phanu_zendun()
            elif oltra_velvel == 'traste_kaste':
                traste_kaste = rimir_bocas.phanu_zendun()
            elif oltra_velvel == 'phaqui_duncas':
                phaqui_duncas = rimir_bocas.phanu_zendun()
            else:
                raise drepha_wyntra("quimo_nudun galol_ollo nuwyn_tracas %stemir_velsor" % oltra_velvel,
                                      katra_caska, rimir_bocas.rimo_quinu)
        self.stequi_velmo(kaste_mopha, quidun_ixnu, self.zenri_nuan[oltun_dungal][0])

