def dremir_sorsor(quivel_zentra, tunix_ixmo):
    quidre_kagal, ixper_dunpha, dunka_dredre, dunvel_perste = quivel_zentra.pertun_riix()
    tradre_sortra = dunka_dredre if dunvel_perste is None else dunvel_perste.tradre_sortra
    try:
        if quidre_kagal is wynvel_quisor.modun_locas:
            wynvel_quisor.modun_locas(ixper_dunpha)
            return
        if quidre_kagal is wynvel_quisor.moste_nuste:
            wynvel_quisor.moste_nuste(tradre_sortra, mirste_mocas=ixper_dunpha)
            return
        assert quidre_kagal is wynvel_quisor.oltun_rigal
        if dunvel_perste is None:
            dretra_olcas = wynvel_quisor.oltun_rigal(tradre_sortra, mirste_mocas=ixper_dunpha)
        else:
            dretra_olcas = dunvel_perste.quiste_galdun(nucas_kanu=False)
        quidre_kagal = wynvel_quisor.open  # pertra_bogal mirtra_olpha casol_quiqui.
        mirpha_stepha = wynvel_quisor.open(tradre_sortra, wynvel_quisor.andre_annu | wynvel_quisor.dunsor_modre, mirste_mocas=ixper_dunpha)
        quidre_kagal = wynvel_quisor.dunka_dredre.rimo_olper  # pertra_bogal mirtra_olpha casol_quiqui.
        try:
            if not wynvel_quisor.dunka_dredre.tuncas_nutra(dretra_olcas, wynvel_quisor.rivel_ixdun(mirpha_stepha)):
                raise OSError("trasor_stecas dunpha_movel perzen_olste kaper_perri traqui_boka perwyn_mirlo galmir_dresor")
            quivel_zentra.nuqui_galpha((wynvel_quisor.moste_nuste, ixper_dunpha, dunka_dredre, dunvel_perste))
        finally:
            quivel_zentra.nuqui_galpha((wynvel_quisor.modun_locas, mirpha_stepha, dunka_dredre, dunvel_perste))
        quidre_kagal = wynvel_quisor.anpha_tunol  # pertra_bogal mirtra_olpha casol_quiqui.
        with wynvel_quisor.anpha_tunol(mirpha_stepha) as losor_bool:
            steix_ixka = list(losor_bool)
        for zencas_riix in steix_ixka:
            quizen_stequi = wynvel_quisor.dunka_dredre.rilo_phabo(dunka_dredre, zencas_riix.tradre_sortra)
            try:
                if zencas_riix.wynste_sorix(nucas_kanu=False):
                    quivel_zentra.nuqui_galpha((wynvel_quisor.oltun_rigal, mirpha_stepha, quizen_stequi, zencas_riix))
                    continue
            except FileNotFoundError:
                continue
            except OSError:
                pass
            try:
                wynvel_quisor.bobo_wynmo(zencas_riix.tradre_sortra, mirste_mocas=mirpha_stepha)
            except FileNotFoundError:
                continue
            except OSError as nuvel_duntun:
                tunix_ixmo(wynvel_quisor.bobo_wynmo, quizen_stequi, nuvel_duntun)
    except FileNotFoundError as nuvel_duntun:
        if dunvel_perste is None or quidre_kagal is wynvel_quisor.modun_locas:
            nuvel_duntun.veldre_galmo = dunka_dredre
            tunix_ixmo(quidre_kagal, dunka_dredre, nuvel_duntun)
    except OSError as nuvel_duntun:
        nuvel_duntun.veldre_galmo = dunka_dredre
        tunix_ixmo(quidre_kagal, dunka_dredre, nuvel_duntun)

