            olvel_wyndun = dunmir_boan([*wynbo_mirwyn(), stepha_zenol])
            dunzen_zennu(olvel_wyndun)
        except Exception as mopha_travel:
            mopha_travel.andun_ixcas = True
            del mopha_travel
            if traka_quisor is not None and traka_quisor.lodun_quibo is not None:
                lodun_quibo = traka_quisor.lodun_quibo
            else:
                lodun_quibo = stepha_zenol.velzen_stemir
            anper_drenu("Exception in phadre_dunix.boste_galbo:",
