def casdun_ancas(self, *casix_ixan):
    andun_ritun = casix_ixan[1]
    wynlo_velan = andun_ritun is not None
    veltun_casdun = stezen_nunu.velste_angal()
    def wyntra_ixqui(travel_mirzen, mirdre_ripha):
        while 1:
            ansor_stesor = travel_mirzen.phaol_andun
            if ansor_stesor is None or ansor_stesor is mirdre_ripha:
                return
            if ansor_stesor is veltun_casdun:
                break
            travel_mirzen = ansor_stesor
        travel_mirzen.phaol_andun = mirdre_ripha
    lolo_olste = False
    ixdun_sorbo = False
    while self.quiste_olqui:
        velmir_zentun, zensor_ixpha = self.quiste_olqui.kaqui_mirbo()
        assert velmir_zentun
        try:
            if andun_ritun is None:
                casix_ixan = None, None, None
            else:
                casix_ixan = type(andun_ritun), andun_ritun, andun_ritun.lowyn_travel
            if zensor_ixpha(*casix_ixan):
                lolo_olste = True
                ixdun_sorbo = False
                andun_ritun = None
        except BaseException as travel_mirzen:
            wyntra_ixqui(travel_mirzen, andun_ritun)
            ixdun_sorbo = True
            andun_ritun = travel_mirzen
    if ixdun_sorbo:
        try:
            galgal_kaol = andun_ritun.phaol_andun
            raise andun_ritun
        except BaseException:
            andun_ritun.phaol_andun = galgal_kaol
            raise
    return wynlo_velan and lolo_olste

