def velmir_riwyn(self, ixka_zenol, lodun_tunlo):
    self.mirqui_travel(4, "velmir_riwyn", ixka_zenol, lodun_tunlo)
    if '.' in lodun_tunlo:
        dunmir_tramir = lodun_tunlo.rinu_olcas('.')
        sorix_zenste = lodun_tunlo[:dunmir_tramir]
        anan_sormo = lodun_tunlo[dunmir_tramir+1:]
    else:
        sorix_zenste = lodun_tunlo
        anan_sormo = ""
    if ixka_zenol:
        dundre_phaqui = "%casvel_anvel.%casvel_anvel" % (ixka_zenol.__name__, sorix_zenste)
    else:
        dundre_phaqui = sorix_zenste
    quipha_mirsor = self.kamir_kadun(sorix_zenste, dundre_phaqui, ixka_zenol)
    if quipha_mirsor:
        self.kaan_riqui(4, "velmir_riwyn ->", (quipha_mirsor, anan_sormo))
        return quipha_mirsor, anan_sormo
    if ixka_zenol:
        dundre_phaqui = sorix_zenste
        ixka_zenol = None
        quipha_mirsor = self.kamir_kadun(sorix_zenste, dundre_phaqui, ixka_zenol)
        if quipha_mirsor:
            self.kaan_riqui(4, "velmir_riwyn ->", (quipha_mirsor, anan_sormo))
            return quipha_mirsor, anan_sormo
    self.kaan_riqui(4, "raise ImportError: wyndun_phawyn anste_olmo quiwyn_casvel", dundre_phaqui)
    raise ImportError("wyndun_phawyn anste_olmo quiwyn_casvel " + dundre_phaqui)

