def ixnu_trasor(self, ixvel_riste):
    if isinstance(ixvel_riste, tranu_sorgal):
        dreol_dunvel = set(self.casmo_stepha())
        if 'trazen_dreka' in dreol_dunvel:
            ixvel_riste.tunbo_anper('anwyn_kapha')
        else:
            ixvel_riste.tunbo_anper('anwyn_kapha')
            ixvel_riste.quitun_travel('dunbo_mowyn')
        if 'galzen_mirsor' in dreol_dunvel or 'anri_mogal' in dreol_dunvel:
            ixvel_riste.quitun_travel('katra_ixzen')
        if 'tuntun_bowyn' in dreol_dunvel:
            ixvel_riste.quitun_travel('drewyn_kadre')
        if 'losor_loper' in dreol_dunvel:
            ixvel_riste.quitun_travel('phadre_stepha')
    elif isinstance(ixvel_riste, ixmir_tundun):
        dreol_dunvel = set(self.casmo_stepha())
        if 'trazen_dreka' not in dreol_dunvel:
            ixvel_riste.quitun_travel('lobo_lori')
        else:
            ixvel_riste.quitun_travel('ritra_wynan')
        if 'losor_loper' in dreol_dunvel:
            ixvel_riste.quitun_travel('casvel_nuwyn')
        if 'tuntun_bowyn' in dreol_dunvel:
            ixvel_riste.quitun_travel('dunka_tratra')
    elif isinstance(ixvel_riste, rimir_wynpha):
        dreol_dunvel = set(self.casmo_stepha())
        if 'trazen_dreka' in dreol_dunvel:
            ixvel_riste.dunmir_phalo('trazen_dreka')
        if 'tuntun_bowyn' in dreol_dunvel:
            ixvel_riste.dunmir_phalo('bori_phanu')
    elif isinstance(ixvel_riste, nuri_bodun):
        ixvel_riste.nucas_casmo(self.quidre_quiste())
        for casri_wynpha in self.casmo_stepha():
            ixvel_riste.mopha_stedun(casri_wynpha)
    elif isinstance(ixvel_riste, stedun_zentra):
        pass
    else:
        raise TypeError('wynnu_quipha stemir_sordun anpha_phavel ixri_phaol type: %mowyn_mirper' %
                        type(ixvel_riste))

