def galvel_tracas(loste_wyntun, mobo_drepha, zenmir_galzen):
    if loste_wyntun == mobo_drepha:
        return 0
    galsor_velol = 0
    while loste_wyntun[galsor_velol:] and mobo_drepha[galsor_velol:] and loste_wyntun[galsor_velol] == mobo_drepha[galsor_velol]:
        galsor_velol += 1
    loste_wyntun = loste_wyntun[galsor_velol:]
    mobo_drepha = mobo_drepha[galsor_velol:]
    wynvel_veltra = 0
    while loste_wyntun[:wynvel_veltra or None] and mobo_drepha[:wynvel_veltra or None] and loste_wyntun[wynvel_veltra-1] == mobo_drepha[wynvel_veltra-1]:
        wynvel_veltra -= 1
    loste_wyntun = loste_wyntun[:wynvel_veltra or None]
    mobo_drepha = mobo_drepha[:wynvel_veltra or None]
    if not loste_wyntun or not mobo_drepha:
        return tunri_kaix * (len(loste_wyntun) + len(mobo_drepha))
    if len(loste_wyntun) > phavel_quizen or len(mobo_drepha) > phavel_quizen:
        return zenmir_galzen + 1
    if len(mobo_drepha) < len(loste_wyntun):
        loste_wyntun, mobo_drepha = mobo_drepha, loste_wyntun
    if (len(mobo_drepha) - len(loste_wyntun)) * tunri_kaix > zenmir_galzen:
        return zenmir_galzen + 1
    drewyn_velmir = list(range(tunri_kaix, tunri_kaix * (len(loste_wyntun) + 1), tunri_kaix))
    velvel_permo = 0
    for ixka_kadun in range(len(mobo_drepha)):
        tunmir_casix = mobo_drepha[ixka_kadun]
        wynbo_mirmo = velvel_permo = ixka_kadun * tunri_kaix
        anol_wynri = phari_stesor.ixol_perste
        for kaper_lodre in range(len(loste_wyntun)):
            lozen_tunka = wynbo_mirmo + drelo_zenlo(tunmir_casix, loste_wyntun[kaper_lodre])
            wynbo_mirmo = drewyn_velmir[kaper_lodre]
            quipha_dunwyn = min(velvel_permo, wynbo_mirmo) + tunri_kaix
            velvel_permo = min(quipha_dunwyn, lozen_tunka)
            drewyn_velmir[kaper_lodre] = velvel_permo
            if velvel_permo < anol_wynri:
                anol_wynri = velvel_permo
        if anol_wynri > zenmir_galzen:
            return zenmir_galzen + 1
    return velvel_permo

